INSERT INTO dd_capacites_speciales
  (cap_id, cap_nom, cap_description, cap_type, cap_classe_initiale)
VALUES
  (601, 'Rage', '<p>Vous pouvez vous animer d’une force primitive appelée Rage, qui vous investit d’une puissance et d’une résistance accrues. Vous pouvez entrer en Rage, par une action Bonus, si vous ne portez pas d’armure lourde.</p><p>Vous pouvez entrer en Rage autant de fois par jour qu’indiqué dans la colonne Rages de la table Aptitudes du Barbare, pour votre niveau de Barbare. Vous en regagnez une utilisation lorsque vous terminez un Repos court, et récupérez tout le quota en terminant un Repos long.</p><p>Tant que votre Rage est active, les règles suivantes s’appliquent.</p><p><b>Résistance aux dégâts.</b> Vous bénéficiez de la Résistance aux dégâts contondants, perforants et tranchants.</p><p><b>Dégâts de Rage.</b> Lorsque vous effectuez une attaque basée sur la Force, que ce soit avec une arme ou à mains nues, et que vous infligez des dégâts à la cible, vous bénéficiez pour ces dégâts d’un bonus qui augmente lorsque vous gagnez des niveaux de Barbare, comme indiqué à la colonne Dégâts de Rage de la table Aptitudes du Barbare.</p><p><b>Avantage en Force.</b> Vous avez l’Avantage aux tests de Force et aux jets de sauvegarde de Force.</p><p><b>Ni Concentration ni sorts.</b> Vous ne pouvez pas maintenir votre Concentration ni lancer de sorts.</p><p><b>Durée.</b> La Rage persiste jusqu’à la fin de votre tour suivant, mais se termine prématurément si vous enfilez une armure lourde ou subissez l’état Neutralisé. Si votre Rage est encore active lorsque votre tour suivant intervient, vous pouvez la prolonger d’un round par n’importe laquelle des choses suivantes :</p><ul><li>Effectuer un jet d’attaque contre un ennemi.</li><li>Contraindre un ennemi à effectuer un jet de sauvegarde.</li><li>Entreprendre une action Bonus pour prolonger votre Rage.</li></ul><p>Chaque fois que la Rage est prolongée, elle persiste jusqu’à la fin de votre tour suivant. Vous pouvez maintenir votre Rage pendant un maximum de 10 minutes.</p>', '', 51),
  (602, 'Bottes d’arme', '<p>Votre entraînement martial vous permet de recourir à la botte de deux types d’arme de corps à corps courante ou de guerre de votre choix, par exemple la hache à deux mains et la hachette. Chaque fois que vous terminez un Repos long, vous pouvez accomplir des exercices martiaux pour changer l’un de ces choix.</p><p>Lorsque vous atteignez certains niveaux de Barbare, vous recevez la faculté de recourir à la botte d’autres types d’arme, comme indiqué à la colonne Bottes d’arme de la table Aptitudes du Barbare.</p>', '', 51),
  (603, 'Défense sans armure', '<p>Tant que vous ne portez pas d’armure, votre classe d’armure de base est égale à 10 + vos modificateurs de Dextérité et de Constitution. Vous conservez ce bénéfice si vous vous servez d’un bouclier.</p>', '', 51),
  (604, 'Sens du danger', '<p>Vous acquérez un talent surnaturel qui vous permet d’esquiver plus aisément les dangers que d’autres remarqueraient trop tard. Vous avez l’Avantage aux jets de sauvegarde de Dextérité, sauf si vous subissez l’état Neutralisé.</p>', '', 51),
  (605, 'Témérité', '<p>Vous pouvez renoncer à toute velléité de vous défendre au profit d’une férocité accrue. Quand vous effectuez le premier jet d’attaque de votre tour, vous pouvez décider d’attaquer avec témérité. Ce faisant, vous avez l’Avantage aux jets d’attaque basés sur la Force jusqu’au début de votre tour suivant, mais les jets d’attaque contre vous ont l’Avantage dans le même intervalle.</p>', '', 51),
  (606, 'Savoir primal', '<p>Vous recevez la maîtrise d’une autre compétence de votre choix dans la liste de compétences disponibles aux Barbares de niveau 1.</p><p>De plus, tant que votre Rage est active, vous pouvez canaliser les énergies primales lorsque vous tentez certaines tâches ; chaque fois que vous effectuez un test de caractéristique avec l’une des compétences suivantes, vous pouvez en faire un test de Force même s’il s’agit normalement d’une autre caractéristique : Acrobaties, Discrétion, Intimidation, Perception et Survie. Lorsque vous recourez à cette aptitude, votre Force illustre les énergies primales qui vous animent, et affûtent vos sens, votre aplomb et votre agilité.</p>', '', 51),
  (607, 'Sous-classe de Barbare', '<p>Vous recevez la sous-classe de Barbare de votre choix. La sous-classe Voie du Berserker est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Barbare. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel de Barbare.</p>', '', 51),
  (608, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Barbare 8, 12 et 16.</p>', '', 51),
  (609, 'Attaque supplémentaire', '<p>Vous pouvez attaquer deux fois au lieu d’une lorsque vous entreprenez l’action Attaque à votre tour.</p>', '', 51),
  (610, 'Déplacement rapide', '<p>Votre Vitesse augmente de 3 m tant que vous ne portez pas d’armure lourde.</p>', '', 51),
  (611, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Barbare que vous avez choisie, correspondant à ce niveau.</p>', '', 51),
  (612, 'Bond instinctif', '<p>Dans le cadre de l’action Bonus entreprise pour entrer en Rage, vous pouvez vous déplacer à concurrence de la moitié de votre Vitesse.</p>', '', 51),
  (613, 'Instinct sauvage', '<p>Votre instinct s’est affûté au point que vous avez l’Avantage aux jets d’Initiative.</p>', '', 51),
  (614, 'Coup brutal', '<p>Si vous recourez à Témérité, vous pouvez renoncer à l’Avantage pour un jet d’attaque basé sur la Force, de votre choix et à votre tour. Le jet d’attaque retenu ne doit pas avoir le Désavantage. Si ce jet d’attaque touche, la cible subit 1d10 dégâts supplémentaires du même type qu’infligé par l’arme ou à mains nues, et vous pouvez lui imposer l’effet de Coup brutal de votre choix. Vous disposez des options d’effet suivantes.</p><p><b>Coup appuyé.</b> La cible est repoussée de vous de 4,50 m, en ligne droite. Vous pouvez alors vous déplacer en ligne droite vers la cible à concurrence de la moitié de votre Vitesse sans provoquer d’attaques d’Opportunité.</p><p><b>Coup au jarret.</b> La Vitesse de la cible est réduite de 4,50 m jusqu’au début de votre tour suivant. Une même cible ne peut être affectée que par un seul Coup au jarret à la fois ; le plus récent.</p>', '', 51),
  (615, 'Rage implacable', '<p>Votre Rage vous permet de continuer à combattre malgré les pires blessures. Si vous tombez à 0 point de vie alors que votre Rage est active et que vous ne mourez pas sur le coup, vous pouvez effectuer un jet de sauvegarde de Constitution DD 10. En cas de réussite, vos points de vie se retrouvent en fait au double de votre niveau de Barbare.</p><p>Par la suite et chaque fois que vous réutilisez cette aptitude, le DD augmente de 5. Lorsque vous terminez un Repos court ou long, le DD retombe à 10.</p>', '', 51),
  (616, 'Coup brutal amélioré', '<p>Vous avez développé de nouveaux coups féroces. Les effets ci-après figurent désormais dans vos options de Coup brutal.</p><p><b>Coup stupéfiant.</b> La cible a le Désavantage à son prochain jet de sauvegarde et ne peut pas effectuer d’attaque d’Opportunité jusqu’au début de votre tour suivant.</p><p><b>Coup déchirant.</b> Le prochain jet d’attaque effectué avant le début de votre tour suivant par une autre créature contre la cible bénéficie d’un bonus de +5. Un même jet d’attaque ne peut bénéficier que d’un seul bonus de Coup déchirant.</p>', '', 51),
  (617, 'Rage persistante', '<p>Lorsque vous jouez l’Initiative, vous pouvez récupérer toutes vos utilisations de Rage. Après avoir récupéré ainsi vos utilisations de Rage, vous devez terminer un Repos long pour pouvoir le refaire.</p><p>De plus, votre Rage est si féroce qu’elle persiste désormais 10 minutes sans vous demander de la prolonger activement de round en round. Votre Rage prend fin prématurément si vous subissez l’état Inconscient (l’état Neutralisé seul n’y met plus fin) ou si vous enfilez une armure lourde.</p>', '', 51),
  (618, 'Coup brutal amélioré', '<p>Les dégâts supplémentaires de votre Coup brutal passent à 2d10. De plus, vous pouvez appliquer simultanément deux effets différents de l’aptitude lorsque vous recourez à Coup brutal.</p>', '', 51),
  (619, 'Puissance indomptable', '<p>Si le total que vous obtenez lors d’un test ou jet de sauvegarde de Force est inférieur à votre valeur de Force, vous pouvez utiliser celle-ci à la place du total obtenu.</p>', '', 51),
  (620, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur d’attaque irrésistible est recommandé.</p>', '', 51),
  (621, 'Champion primitif', '<p>Vous incarnez la puissance primitive. Vos valeurs de Force et de Constitution augmentent de 4, jusqu’à un maximum de 25.</p>', '', 51),
  (622, 'Inspiration bardique', '<p>Vous pouvez inspirer autrui, surnaturellement, par vos paroles, votre musique ou vos danses. Cette inspiration est représentée par votre dé d’Inspiration bardique, un d6.</p><p><b>Utilisation de l’Inspiration bardique.</b> Par une action Bonus, vous pouvez inspirer une autre créature qui vous voit ou vous entend dans un rayon de 18 m. Cette créature reçoit l’un de vos dés d’Inspiration bardique. Une même créature ne peut pas disposer de plus d’un dé d’Inspiration bardique à la fois.</p><p>Une fois au cours de l’heure à venir, lorsque la créature rate un Test d20, elle peut lancer le dé d’Inspiration bardique pour en ajouter le résultat au Test d20, ce qui peut convertir l’échec en réussite. Le dé d’Inspiration bardique est dépensé dès qu’il est lancé.</p><p><b>Nombre d’utilisations.</b> Vous pouvez conférer l’Inspiration bardique autant de fois que votre modificateur de Charisme (minimum d’une fois) et vous récupérez ce quota en terminant un Repos long.</p><p><b>À plus haut niveau.</b> Votre dé d’Inspiration bardique change lorsque vous atteignez certains niveaux de Barde, comme indiqué à la colonne Dé d’inspiration de la table « Aptitudes du Barde ». Le dé devient un d8 au niveau 5, un d10 au niveau 10 et un d12 au niveau 15.</p>', '', 53),
  (623, 'Sorts', '<p>Vous avez appris à lancer des sorts au gré de votre expression artistique. Reportez-vous à la section « Sorts » pour les règles d’incantation. Les informations ci-après expliquent comment utiliser ces règles avec les sorts de Barde, qui figurent dans la liste Sorts de Barde, plus loin dans le descriptif de la classe.</p><p><b>Sorts mineurs.</b> Vous connaissez deux sorts mineurs que vous choisissez dans la liste des sorts de Barde. Lumières dansantes et moquerie cruelle sont recommandés.</p><p>Chaque fois que vous gagnez un niveau de Barde, vous pouvez remplacer l’un de vos sorts mineurs par un autre sort mineur de votre choix dans la liste du Barde.</p><p>Lorsque vous atteignez le niveau 4 de Barde, puis le niveau 10, vous apprenez un autre sort mineur de votre choix issu de la liste du Barde, comme indiqué à la colonne Sorts mineurs de la table « Aptitudes du Barde ».</p><p><b>Emplacements de sort.</b> La table « Aptitudes du Barde » vous indique le nombre d’emplacements de sort dont vous disposez pour lancer vos sorts du 1er niveau et supérieur. Vous récupérez tous les emplacements dépensés en terminant un Repos long.</p><p><b>Sorts préparés du 1er niveau et plus.</b> Vous devez préparer la liste des sorts du 1er niveau et supérieur que cette aptitude vous permet de lancer. Pour commencer, choisissez quatre sorts du 1er niveau issus de la liste de sorts du Barde. Charme-personne, couleurs dansantes, mot de guérison et murmures dissonants sont recommandés.</p><p>Le nombre de sorts de votre liste augmente à mesure que vous recevez des niveaux de Barde, comme l’indique la colonne Sorts préparés de la table « Aptitudes du Barde ». Chaque fois que ce nombre augmente, choisissez des sorts de Barde supplémentaires jusqu’à ce que le nombre de sorts de votre liste corresponde au nombre indiqué dans la table. Ces sorts doivent être d’un niveau pour lequel vous disposez d’emplacements de sort. Si, par exemple, vous êtes un Barde de niveau 3, votre liste de sorts préparés peut inclure six sorts de Barde du 1er ou 2e niveau, répartis à votre guise.</p><p>Si une autre aptitude de Barde vous octroie des sorts toujours préparés, ces sorts ne sont pas décomptés du nombre de sorts que vous pouvez préparer avec la présente aptitude, mais ils sont considérés pour vous comme des sorts de Barde.</p><p><b>Modification des sorts préparés.</b> Chaque fois que vous gagnez un niveau de barde, vous pouvez remplacer un sort de votre liste par un autre sort de barde pour lequel vous disposez d’au moins un emplacement.</p><p><b>Caractéristique d’incantation.</b> Le Charisme est la caractéristique d’incantation de vos sorts de Barde.</p><p><b>Focaliseur d’incantation.</b> Vous pouvez vous servir d’un instrument de musique comme focaliseur d’incantation de vos sorts de Barde.</p>', '', 53),
  (624, 'Expertise', '<p>Vous recevez l’Expertise (cf. « Glossaire de règles ») dans deux de vos maîtrises de compétence au choix. Persuasion et Représentation sont recommandées si vous en avez la maîtrise.</p><p>Au niveau 9 de Barde, vous recevez l’Expertise dans deux maîtrises de compétences supplémentaires au choix.</p>', '', 53),
  (625, 'Touche-à-tout', '<p>Vous pouvez ajouter la moitié de votre bonus de maîtrise (arrondi à l’inférieur) à tout test de caractéristique que vous effectuez sans avoir la maîtrise de la compétence associée, à condition que votre bonus de maîtrise ne s’y applique pas par ailleurs.</p><p>Exemple : si vous effectuez un test de Force (Athlétisme) sans avoir la maîtrise d’Athlétisme, vous pouvez ajouter la moitié de votre bonus de maîtrise au test.</p>', '', 53),
  (626, 'Sous-classe de Barde', '<p>Vous recevez la sous-classe de Barde de votre choix. La sous-classe Collège du Savoir est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Barde. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel de Barde.</p>', '', 53),
  (627, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Barde 8, 12 et 16.</p>', '', 53),
  (628, 'Source d’inspiration', '<p>Vous récupérez désormais tout votre quota d’Inspiration bardique lorsque vous terminez un Repos court ou long.</p><p>De plus, vous pouvez dépenser un emplacement de sort (pas d’action requise) pour récupérer une utilisation d’Inspiration bardique.</p>', '', 53),
  (629, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Barde que vous avez choisie, correspondant à ce niveau.</p>', '', 53),
  (630, 'Contre-charme', '<p>Vous pouvez recourir à des notes de musique ou à des mots de pouvoir pour contrer les effets qui influent sur l’esprit. Si vous ou une créature dans un rayon de 9 m ratez un jet de sauvegarde contre un effet qui impose l’état Charmé ou Effrayé, vous pouvez jouer votre Réaction pour que le JS soit rejoué, le nouveau jet se faisant avec l’Avantage.</p>', '', 53),
  (631, 'Secrets magiques', '<p>Vous avez appris les secrets de diverses traditions magiques. Chaque fois que vous atteignez un niveau de Barde (y compris le présent niveau) et que le nombre de Sorts préparés augmente dans la table Aptitudes du Barde, vous pouvez choisir l’un de vos nouveaux sorts préparés dans la liste du Barde, du Clerc, du Druide ou du Magicien, sachant que ces sorts sont considérés pour vous comme des sorts de Barde (vous trouverez ces listes dans la section de chaque classe correspondante). De plus, chaque fois que vous remplacez un sort préparé pour la classe de Barde, vous pouvez le remplacer par un sort issu de n’importe laquelle de ces listes.</p>', '', 53),
  (632, 'Inspiration supérieure', '<p>Lorsque vous lancez l’Initiative, vous récupérez des utilisations d’Inspiration bardique s’il vous en reste une ou moins, jusqu’à en avoir deux.</p>', '', 53),
  (633, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur de mémoire magique est recommandé.</p>', '', 53),
  (634, 'Verbe de la création', '<p>Vous avez maîtrisé deux des paroles du Verbe de la création : celles de la vie et de la mort. Les sorts mot de pouvoir guérisseur et mot de pouvoir mortel sont désormais constamment préparés en ce qui vous concerne. Lorsque vous lancez l’un de ces sorts, vous pouvez cibler une seconde créature qui se trouve dans un rayon de 3 m de la première cible.</p>', '', 53),
  (635, 'Sorts', '<p>Vous avez appris à lancer des sorts grâce à la prière et à la méditation. Reportez-vous à la section « Sorts » pour les règles d’incantation. Les informations ci-après expliquent comment utiliser ces règles avec les sorts de Clerc, qui figurent dans la liste Sorts de Clerc, plus loin dans le descriptif de la classe.</p><p><b>Sorts mineurs.</b> Vous connaissez trois sorts mineurs que vous choisissez dans la liste de sorts du Clerc. Assistance, flamme sacrée et thaumaturgie sont recommandés.</p><p>Chaque fois que vous gagnez un niveau de Clerc, vous pouvez remplacer l’un de vos sorts mineurs par un autre sort mineur de votre choix dans la liste du Clerc.</p><p>Lorsque vous atteignez le niveau 4 de Clerc, puis le niveau 10, vous apprenez un autre sort mineur de votre choix issu de la liste du Clerc, comme indiqué à la colonne Sorts mineurs de la table « Aptitudes du Clerc ».</p><p><b>Emplacements de sort.</b> La table « Aptitudes du Clerc » vous indique le nombre d’emplacements de sort dont vous disposez pour lancer vos sorts du 1er niveau et supérieur. Vous récupérez tous les emplacements dépensés en terminant un Repos long.</p><p><b>Sorts préparés du 1er niveau et plus.</b> Vous devez préparer la liste des sorts du 1er niveau et supérieur que cette aptitude vous permet de lancer. Pour commencer, choisissez quatre sorts du 1er niveau issus de la liste de sorts du Clerc. Bénédiction, bouclier de la foi, rayon traçant et soins sont recommandés.</p><p>Le nombre de sorts de votre liste augmente à mesure que vous recevez des niveaux de Clerc, comme l’indique la colonne Sorts préparés de la table « Aptitudes du Clerc ». Chaque fois que ce nombre augmente, choisissez des sorts de Clerc supplémentaires jusqu’à ce que le nombre de sorts de votre liste corresponde au nombre indiqué dans la table. Ces sorts doivent être d’un niveau pour lequel vous disposez d’emplacements de sort. Si, par exemple, vous êtes un Clerc de niveau 3, votre liste de sorts préparés peut inclure six sorts de Clerc du 1er ou 2e niveau, répartis à votre guise.</p><p>Si une autre aptitude de Clerc vous octroie des sorts toujours préparés, ces sorts ne sont pas décomptés du nombre de sorts que vous pouvez préparer avec la présente aptitude, mais ils sont considérés pour vous comme des sorts de Clerc.</p><p><b>Modification des sorts préparés.</b> Chaque fois que vous terminez un Repos long, vous pouvez changer votre liste de sorts préparés en remplaçant des sorts par d’autres sorts de clerc pour lesquels vous disposez d’emplacements.</p><p><b>Caractéristique d’incantation.</b> La Sagesse est la caractéristique d’incantation de vos sorts de clerc.</p><p><b>Focaliseur d’incantation.</b> Vous pouvez vous servir d’un symbole sacré comme focaliseur d’incantation de vos sorts de clerc.</p>', '', 54),
  (636, 'Ordre divin', '<p>Vous consacrez votre existence à l’un des rôles sacrés suivants, au choix.</p><p><b>Protecteur.</b> Combattant chevronné, vous recevez la maîtrise des armes de guerre et la formation aux armures lourdes.</p><p><b>Thaumaturge.</b> Vous connaissez un sort mineur supplémentaire issu de la liste du Clerc. De plus, votre lien mystique vous octroie un bonus aux tests d’Intelligence (Arcanes et Religion). Ce bonus est égal à votre modificateur de Sagesse (minimum +1).</p>', '', 54),
  (637, 'Conduit divin', '<p>Vous pouvez canaliser l’énergie divine directement depuis les Plans Extérieurs afin de produire des effets magiques. Vous débutez avec deux effets de ce type : Étincelle divine et Renvoi des morts-vivants, décrits ci-après. Chaque fois que vous recourez au Conduit divin de cette classe, vous choisissez l’effet associé que vous souhaitez générer. Vous recevez de nouvelles options à plus haut niveau de Clerc.</p><p>Vous pouvez utiliser deux fois le Conduit divin de cette classe. Vous en regagnez une utilisation lorsque vous terminez un Repos court, et récupérez tout le quota en terminant un Repos long. Vous recevrez des utilisations supplémentaires en atteignant certains niveaux de Clerc, comme indiqué en colonne Conduit divin de la table « Aptitudes du Clerc ».</p><p>Si un effet de Conduit divin entraîne un jet de sauvegarde, le DD est égal au DD de sauvegarde des sorts de l’aptitude Sorts de cette classe.</p><p><b>Étincelle divine.</b> Au prix de l’action Magie, vous pointez votre symbole sacré vers une autre créature que vous voyez dans un rayon de 9 m pour concentrer vers elle les énergies divines. Lancez 1d8 et ajoutez-y votre modificateur de Sagesse. Soit vous restituez à la créature autant de points de vie que le total obtenu, soit vous la contraignez à effectuer un jet de sauvegarde de Constitution. Si elle rate ce JS, la créature subit autant de dégâts nécrotiques ou radiants (vous choisissez) que le total obtenu par votre jet. En cas de réussite, la créature subit la moitié de ces dégâts.</p><p>Vous ajoutez un d8 lorsque vous atteignez les niveaux 7 (2d8), 13 (3d8) et 18 (4d8) de Clerc.</p><p><b>Renvoi des morts-vivants.</b> Au prix de l’action Magie, vous brandissez votre symbole sacré pour condamner les Morts-vivants. Chaque Mort-vivant de votre choix dans un rayon de 9 m effectue un jet de sauvegarde de Sagesse. En cas d’échec, la créature subit les états Effrayé et Neutralisé pendant 1 minute. Pour toute la durée, elle s’efforce de s’éloigner de vous autant que possible à chacun de ses tours. Cet effet prend fin prématurément si la créature subit des dégâts, si vous subissez l’état Neutralisé ou si vous mourez.</p>', '', 54),
  (638, 'Sous-classe de Clerc', '<p>Vous recevez la sous-classe de Clerc de votre choix. La sous-classe Domaine de la Vie est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Clerc. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel de Clerc.</p>', '', 54),
  (639, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Clerc 8, 12 et 16.</p>', '', 54),
  (640, 'Calcination de Mort-vivant', '<p>Chaque fois que vous recourez à Renvoi des morts-vivants, vous pouvez lancer autant de d8 que votre modificateur de Sagesse (minimum 1d8) et les ajouter. Chaque Mort-vivant qui rate son JS contre cette utilisation de Renvoi des morts-vivants subit autant de dégâts radiants que le total de ces dés. Ces dégâts ne mettent pas fin aux effets du renvoi.</p>', '', 54),
  (641, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Clerc que vous avez choisie, correspondant à ce niveau.</p>', '', 54),
  (642, 'Impacts bénis', '<p>La puissance divine vous anime au combat. Vous recevez l’une des options suivantes de votre choix (si vous avez obtenu une de ces options par une sous-classe de Clerc issue d’un ouvrage plus ancien, ne retenez que l’option choisie par la présente aptitude).</p><p><b>Impact divin.</b> Une fois à chacun de vos tours, lorsque vous touchez une créature par un jet d’attaque avec une arme, vous pouvez lui infliger 1d8 dégâts supplémentaires du type que vous choisissez entre nécrotiques et radiants.</p><p><b>Incantation puissante.</b> Ajoutez votre modificateur de Sagesse aux dégâts que vous infligez par tout sort mineur de Clerc.</p>', '', 54),
  (643, 'Intervention divine', '<p>Vous pouvez faire appel à votre divinité ou votre panthéon pour intercéder en votre faveur. Au prix de l’action Magie, choisissez un sort de Clerc du 5e niveau ou inférieur dont l’incantation ne demande pas une Réaction. Dans le cadre de cette même action, vous lancez le sort sans dépenser d’emplacement en vous passant de composantes matérielles. Une fois que vous avez utilisé cette aptitude, vous devez terminer un Repos long pour pouvoir y recourir de nouveau.</p>', '', 54),
  (644, 'Impacts bénis améliorés', '<p>L’option retenue pour Impacts bénis se renforce. Impact divin. Les dégâts supplémentaires de votre</p><p><b>Impact divin passent à 2d8.</b> Incantation puissante. Lorsque vous lancez un sort mineur de Clerc et infligez des dégâts à une créature par son biais, vous pouvez insuffler de la vitalité à une créature dans un rayon de 18 m ou à vous-même, par l’acquisition de points de vie temporaires égaux au double de votre modificateur de Sagesse.</p>', '', 54),
  (645, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur du destin est recommandé.</p>', '', 54),
  (646, 'Intervention divine suprême', '<p>Vous pouvez invoquer une intervention divine encore plus radicale. Lorsque vous recourez à l’aptitude Intervention divine, vous pouvez opter pour souhait comme choix de sort. Dans un tel cas, vous devez terminer 2d4 Repos longs avant de pouvoir réutiliser Intervention divine.</p>', '', 54),
  (647, 'Sorts', '<p>Vous avez appris à lancer des sorts en étudiant les forces mystiques de la nature. Reportez-vous à la section « Sorts » pour les règles d’incantation. Les informations ci-après expliquent comment utiliser ces règles avec les sorts de Druide, qui figurent dans la liste Sorts de Druide, plus loin dans le descriptif de la classe.</p><p><b>Sorts mineurs.</b> Vous connaissez deux sorts mineurs que vous choisissez dans la liste des sorts de Druide. Druidisme et flammes sont recommandés.</p><p>Chaque fois que vous gagnez un niveau de Druide, vous pouvez remplacer l’un de vos sorts mineurs par un autre sort mineur de votre choix dans la liste du Druide.</p><p>Lorsque vous atteignez le niveau 4 de Druide, puis le niveau 10, vous apprenez un autre sort mineur de votre choix issu de la liste du Druide, comme indiqué à la colonne Sorts mineurs de la table « Aptitudes du Druide ».</p><p><b>Emplacements de sort.</b> La table « Aptitudes du Druide » vous indique le nombre d’emplacements de sort dont vous disposez pour lancer vos sorts du 1er niveau et supérieur. Vous récupérez tous les emplacements dépensés en terminant un Repos long.</p><p><b>Sorts préparés du 1er niveau et plus.</b> Vous devez préparer la liste des sorts du 1er niveau et supérieur que cette aptitude vous permet de lancer. Pour commencer, choisissez quatre sorts du 1er niveau issus de la liste de sorts du Druide. Amitié avec les animaux, lueurs féeriques, soins et vague tonnante sont recommandés.</p><p>Le nombre de sorts de votre liste augmente à mesure que vous recevez des niveaux de Druide, comme l’indique la colonne Sorts préparés de la table « Aptitudes du Druide ». Chaque fois que ce nombre augmente, choisissez des sorts de Druide supplémentaires jusqu’à ce que le nombre de sorts de votre liste corresponde au nombre indiqué dans la table. Ces sorts doivent être d’un niveau pour lequel vous disposez d’emplacements de sort. Si, par exemple, vous êtes un Druide de niveau 3, votre liste de sorts préparés peut inclure six sorts de Druide du 1er ou 2e niveau, répartis à votre guise.</p><p>Si une autre aptitude de Druide vous octroie des sorts toujours préparés, ces sorts ne sont pas décomptés du nombre de sorts que vous pouvez préparer avec la présente aptitude, mais ils sont considérés pour vous comme des sorts de Druide.</p><p><b>Modification des sorts préparés.</b> Chaque fois que vous terminez un Repos long, vous pouvez changer votre liste de sorts préparés en remplaçant des sorts par d’autres sorts de Druide pour lesquels vous disposez d’emplacements.</p><p><b>Caractéristique d’incantation.</b> La Sagesse est la caractéristique d’incantation de vos sorts de druide.</p><p><b>Focaliseur d’incantation.</b> Vous pouvez vous servir d’un focaliseur druidique comme focaliseur d’incantation de vos sorts de druide.</p>', '', 55),
  (648, 'Druidique', '<p>Vous connaissez le druidique, la langue secrète des Druides. En apprenant cette langue ancestrale, vous avez aussi percé les mystères magiques de la conversation animale ; le sort communication avec les animaux est toujours préparé en ce qui vous concerne.</p><p>Vous pouvez recourir au druidique pour laisser des messages cachés. Vous et tous ceux qui connaissent cet idiome repérez automatiquement de tels messages. D’autres peuvent aussi détecter la présence de tels signes en réussissant un test d’Intelligence (Investigation) DD 15, mais sont incapables d’en déchiffrer le sens.</p>', '', 55),
  (649, 'Ordre primitif', '<p>Vous consacrez votre existence à l’un des rôles sacrés suivants, au choix.</p><p><b>Mage.</b> Vous connaissez un sort mineur supplémentaire tiré de la liste du Druide. De plus, votre lien mystique vous octroie un bonus aux tests d’Intelligence (Arcanes et Nature). Ce bonus est égal à votre modificateur de Sagesse (minimum +1).</p><p><b>Gardien.</b> Combattant chevronné, vous recevez la maîtrise des armes de guerre et la formation aux armures intermédiaires.</p>', '', 55),
  (650, 'Compagnon sauvage', '<p>Vous pouvez convoquer un esprit de la nature qui adopte une forme animale pour vous assister. Au prix de l’action Magie, vous pouvez dépenser un emplacement ou une utilisation de Forme sauvage pour lancer le sort appel de familier sans composantes matérielles.</p><p>Lorsque vous lancez ainsi le sort, le familier est une Fée et disparaît lorsque vous terminez un Repos long.</p>', '', 55),
  (651, 'Forme sauvage', '<p>Le pouvoir de la nature vous permet d’adopter la forme d’un animal. Par une action Bonus, vous vous métamorphosez en Bête, forme apprise par le biais de cette aptitude (cf. Formes connues, plus loin). Vous restez sous cette forme autant d’heures que la moitié de votre niveau de Druide, mais la quittez prématurément si vous recourez de nouveau à Forme sauvage, subissez l’état Neutralisé ou mourez. Vous pouvez aussi quitter la forme par une action Bonus.</p><p><b>Nombre d’utilisations.</b> Vous pouvez recourir deux fois à Forme sauvage. Vous en regagnez une utilisation lorsque vous terminez un Repos court, et récupérez tout le quota en terminant un Repos long.</p><p>Vous en recevez des utilisations supplémentaires à certains niveaux de Druide, comme indiqué à la colonne Forme sauvage de la table « Aptitudes du Druide ».</p><p><b>Formes connues.</b> Vous connaissez quatre formes de Bête pour cette aptitude, choisies parmi les profils de Bête dont le facteur de puissance n’excède pas 1/4 et dépourvus de Vitesse de vol (voir « Animaux » de la section « Monstres » pour quelques options). Araignée, cheval de selle, loup et rat sont recommandés. Chaque fois que vous terminez un Repos long, vous pouvez remplacer l’une de vos formes connues par une autre forme autorisée.</p><p>Lorsque vous atteignez certains niveaux de Druide, votre nombre de formes connues et le facteur de puissance maximal associé augmentent, comme indiqué sur la table Formes de bête. De plus, à partir du niveau 8, vous pouvez adopter une forme dotée d’une Vitesse de vol.</p><p>Si votre maître de jeu l’autorise, vous pouvez consulter d’autres sources pour choisir vos formes connues.</p><p>Formes de bête</p><p>Niveau de Druide</p><p>Formes connues</p><p>FP max. 1/4 1/2</p><p>Vitesse de vol Non Non</p><p>Oui</p><p><b>Règles sous métamorphose.</b> Tant que vous êtes sous forme de bête, vous conservez votre personnalité, vos souvenirs et votre faculté de parole, et les règles suivantes s’appliquent :</p><p><b>Points de vie temporaires.</b> Lorsque vous adoptez une Forme sauvage, vous recevez autant de points de vie temporaires que votre niveau de Druide.</p><p><b>Profil de jeu.</b> Votre profil est remplacé par celui de la Bête choisie, mais vous conservez les aspects suivants : type de créature ; points de vie ; dés de vie ; valeurs d’Intelligence, Sagesse et Charisme ; aptitudes de classe ; langues ; et dons. Vous conservez aussi vos maîtrises de compétence et de jet de sauvegarde, et appliquez le bonus de maîtrise correspondant, et vous recevez les maîtrises de la créature. Quand le modificateur de compétence ou de JS du profil de Bête est supérieur au vôtre, celui de la Bête s’applique.</p><p><b>Pas d’incantation.</b> Vous ne pouvez pas lancer de sorts, mais la métamorphose ne rompt pas votre Concentration, pas plus qu’elle n’interfère avec les sorts que vous avez déjà lancés.</p><p><b>Objets.</b> Votre faculté de manipuler des objets dépend des membres et appendices de la forme et non plus des vôtres. En outre, vous décidez si votre équipement tombe dans votre espace, fusionne avec votre nouvelle forme ou est porté par elle. L’équipement porté fonctionne normalement, mais c’est au MJ de décider si une pièce d’équipement donnée peut être portée par la créature, en fonction de la forme et de la taille de celle-ci. Votre équipement ne change pas de taille ni de forme pour s’adapter à votre silhouette animale ; toute pièce d’équipement que la forme sauvage ne peut pas porter doit soit tomber au sol, soit fusionner avec elle. L’équipement qui fusionne avec la forme reste sans effet tant que vous restez sous cette forme.</p>', '', 55),
  (652, 'Sous-classe de Druide', '<p>Vous recevez la sous-classe de Druide de votre choix. La sous-classe Cercle de la Terre est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Druide. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel de Druide.</p>', '', 55),
  (653, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Druide 8, 12 et 16.</p>', '', 55),
  (654, 'Regain sauvage', '<p>Une fois à chacun de vos tours, s’il ne vous reste aucune utilisation de Forme sauvage, vous pouvez vous en octroyer une en dépensant un emplacement de sort (pas d’action requise).</p><p>De plus, vous pouvez dépenser une utilisation de Forme sauvage (pas d’action requise) pour vous octroyer un emplacement du 1er niveau, après quoi vous devez terminer un Repos long pour le refaire.</p>', '', 55),
  (655, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Druide que vous avez choisie, correspondant à ce niveau.</p>', '', 55),
  (656, 'Fureur élémentaire', '<p>La puissance des éléments coule en vous. Vous recevez l’une des options suivantes, au choix.</p><p><b>Incantation puissante.</b> Ajoutez votre modificateur de Sagesse aux dégâts que vous infligez par tout sort mineur de Druide.</p><p><b>Attaques primitives.</b> Une fois à chacun de vos tours, lorsque vous touchez une créature par un jet d’attaque avec une arme ou une attaque de Bête sous Forme sauvage, vous pouvez infliger à la cible 1d8 dégâts de feu, foudre, froid ou tonnerre (choisissez quand vous touchez).</p>', '', 55),
  (657, 'Fureur élémentaire améliorée', '<p>L’option retenue pour votre Fureur élémentaire se renforce, comme suit.</p><p><b>Incantation puissante.</b> Lorsque vous lancez un sort mineur de Druide avec une portée de 3 m ou plus, cette portée augmente de 90 m.</p><p><b>Attaques primitives.</b> Les dégâts supplémentaires d’Attaques primitives passent à 2d8.</p>', '', 55),
  (658, 'Incantation animale', '<p>Tant que vous êtes sous Forme sauvage, vous pouvez lancer des sorts bien que sous forme de Bête, à l’exception des sorts assortis d’une composante matérielle dont le coût est spécifié ou qui est détruite par l’incantation.</p>', '', 55),
  (659, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur de Déplacement dimensionnel est recommandé.</p>', '', 55),
  (660, 'Archidruide', '<p>La vitalité de la nature s’épanouit en vous, ce qui vous octroie les bénéfices suivants.</p><p><b>Forme sauvage immarcescible.</b> Chaque fois que vous jouez l’Initiative alors que vous n’avez plus d’utilisation de Forme sauvage, vous en récupérez une utilisation.</p><p><b>Mage de dame Nature.</b> Vous pouvez convertir des utilisations de Forme sauvage en emplacement de sort unique (pas d’action requise). Convertissez un certain nombre d’utilisations non dépensées de Forme sauvage en un seul emplacement de sort, chaque utilisation contribuant à 2 niveaux d’emplacement. Exemple : si vous convertissez deux utilisations de Forme sauvage, vous produisez un emplacement du 4e niveau. Une fois que vous avez utilisé ce bénéfice, vous devez terminer un Repos long pour pouvoir y recourir de nouveau.</p><p><b>Longévité.</b> La magie primitive que vous pratiquez ralentit votre vieillissement. Votre corps ne vieillit que d’un an par décennie.</p>', '', 55),
  (661, 'Sorts', '<p>C’est en puisant dans votre magie innée que vous lancez vos sorts. Reportez-vous à la section « Sorts » pour les règles d’incantation. Les informations ci-après expliquent comment utiliser ces règles avec les sorts d’Ensorceleur, qui figurent dans la liste Sorts d’Ensorceleur, plus loin dans le descriptif de la classe.</p><p><b>Sorts mineurs.</b> Vous connaissez quatre sorts mineurs d’Ensorceleur de votre choix. Éruption ensorcelée, lumière, poigne électrique et prestidigitation sont recommandés. Chaque fois que vous gagnez un niveau d’Ensorceleur, vous pouvez remplacer l’un de vos sorts d’Ensorceleur, vous apprenez un autre sort mineur d’Ensorceleur de votre choix, comme indiqué en colonne Sorts mineurs de la table « Aptitudes de l’Ensorceleur ». Emplacements de sort. La table « Aptitudes de l’Ensorceleur » vous indique le nombre d’emplacements de sort dont vous disposez pour lancer vos sorts du 1er niveau et supérieur. Vous récupérez tous les emplacements dépensés en terminant un Repos long. Sorts préparés du 1er niveau et plus. Vous devez préparer la liste des sorts du 1er niveau et supérieur que cette aptitude vous permet de lancer. Pour commencer, choisissez deux sorts d’Ensorceleur du</p><p><b>1er niveau.</b> Détection de la magie et mains brûlantes sont recommandés.</p><p>Le nombre de sorts de votre liste augmente à mesure que vous recevez des niveaux d’Ensorceleur, comme l’indique la colonne Sorts préparés de la table « Aptitudes de l’Ensorceleur ». Chaque fois que ce nombre augmente, choisissez des sorts d’Ensorceleur supplémentaires jusqu’à ce que le nombre de sorts de votre liste corresponde au nombre indiqué dans la table « Aptitudes de l’Ensorceleur ». Ces sorts doivent être d’un niveau pour lequel vous disposez d’emplacements de sort. Si, par exemple, vous êtes un</p><p>Ensorceleur de niveau 3, votre liste de sorts préparés peut inclure six sorts d’Ensorceleur du 1er ou 2e niveau, répartis à votre guise.</p><p>Si une autre aptitude d’Ensorceleur vous octroie des sorts toujours préparés, ces sorts ne sont pas décomptés du nombre de sorts que vous pouvez préparer avec la présente aptitude, mais ils sont considérés pour vous comme des sorts d’Ensorceleur.</p><p><b>Modification des sorts préparés.</b> Chaque fois que vous gagnez un niveau d’Ensorceleur, vous pouvez remplacer un sort de votre liste par un autre sort d’Ensorceleur pour lequel vous disposez d’au moins un emplacement.</p><p><b>Caractéristique d’incantation.</b> Le Charisme est la caractéristique d’incantation de vos sorts d’Ensorceleur.</p><p><b>Focaliseur d’incantation.</b> Vous pouvez vous servir d’un focaliseur arcanique comme focaliseur d’incantation de vos sorts d’Ensorceleur.</p>', '', 56),
  (662, 'Sorcellerie innée', '<p>Un événement de votre passé a laissé une marque indélébile sur vous, faisant éclore une magie bouillonnante. Par une action Bonus, vous pouvez libérer cette magie pendant 1 minute, au cours de laquelle vous recevez les bénéfices suivants :</p><ul><li>Le DD de sauvegarde de vos sorts d’Ensorceleur augmente de 1.</li></ul><ul><li>Vous avez l’Avantage aux jets d’attaque des sorts d’Ensorceleur que vous lancez.</li></ul><p>Vous pouvez recourir à cette aptitude deux fois, et récupérez ce quota en terminant un Repos long.</p>', '', 56),
  (663, 'Réserve arcanique', '<p>Vous pouvez puiser dans la réserve de magie qui sommeille en vous. Cette réserve est figurée par des points de Sorcellerie, qui vous permettent de créer une variété d’effets magiques.</p><p>Vous disposez de 2 points de Sorcellerie et en recevez davantage à mesure que vous atteignez des niveaux plus élevés, comme indiqué en colonne Points de sorcellerie de la table « Aptitudes de l’Ensorceleur ». Vous ne pouvez pas avoir plus de points de Sorcellerie que ce qui est indiqué sur la table à votre niveau. Vous récupérez tous les points de Sorcellerie dépensés en terminant un Repos long.</p><p>Vous pouvez utiliser vos points de Sorcellerie pour alimenter les options ci-dessous, ainsi que d’autres aptitudes comme Métamagie, qui recourent à ces points.</p><p>Conversion d’emplacements de sort en points de Sorcellerie. Dépenser un emplacement de sort vous permet de recevoir un nombre de points de Sorcellerie égal au niveau de l’emplacement (pas d’action requise).</p><p><b>Création d’emplacements de sort.</b> Par une action Bonus, vous pouvez transformer des points de Sorcellerie non dépensés en un emplacement de sort. La table « Création d’emplacements de sort » indique le coût de création d’un emplacement de sort selon son niveau, ainsi que le niveau minimum d’Ensorceleur requis pour créer un tel emplacement. Vous ne pouvez pas créer un emplacement de sort au-dessus du 5e niveau.</p><p>Tout emplacement de sort créé avec cette aptitude disparaît quand vous terminez un Repos long.</p><p>Création d’emplacements de sort</p><p>Niveau d’emplacement de sort</p><p>Coût en points de Sorcellerie</p><p>Niveau d’Ensorceleur minimum</p>', '', 56),
  (664, 'Métamagie', '<p>Grâce à la magie qui bouillonne en vous, vous pouvez altérer les sorts au gré des besoins ; vous recevez deux options de Métamagie au choix parmi les « Options de métamagie » présentées plus loin, dans le descriptif de la classe. Les options choisies vous permettent de modifier ponctuellement le sort que vous lancez. Pour recourir à une option, vous devez dépenser son coût exprimé en points de Sorcellerie.</p><p>Vous ne pouvez appliquer qu’une option de Métamagie à l’incantation d’un sort, sauf si l’une des options précise le contraire.</p><p>Chaque fois que vous gagnez un niveau d’Ensorceleur, vous pouvez remplacer l’une de vos options de Métamagie par une autre qui vous est inconnue. Vous recevez deux options supplémentaires au niveau 10 d’Ensorceleur et deux de plus au niveau 17.</p>', '', 56),
  (665, 'Sous-classe d’Ensorceleur', '<p>Vous recevez la sous-classe d’Ensorceleur de votre choix. La sous-classe Sorcellerie draconique est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux d’Ensorceleur. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel d’Ensorceleur.</p>', '', 56),
  (666, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux d’Ensorceleur 8, 12 et 16.</p>', '', 56),
  (667, 'Restauration ensorcelée', '<p>En terminant un Repos court, vous récupérez les points de Sorcellerie dépensés à concurrence de la moitié de votre niveau d’Ensorceleur (arrondir à l’inférieur). Une fois cette aptitude utilisée, vous devez terminer un Repos long pour pouvoir y recourir de nouveau.</p>', '', 56),
  (668, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Ensorceleur que vous avez choisie, correspondant à ce niveau.</p>', '', 56),
  (669, 'Sorcellerie incarnée', '<p>S’il ne vous reste aucune utilisation de Sorcellerie innée, vous pouvez y recourir en dépensant 2 points de Sorcellerie et l’activez par une action Bonus.</p><p>En outre et tant que votre aptitude Sorcellerie innée est active, vous pouvez utiliser jusqu’à deux de vos options de Métamagie pour chaque sort que vous lancez.</p>', '', 56),
  (670, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur de Déplacement dimensionnel est recommandé.</p>', '', 56),
  (671, 'Apothéose arcanique', '<p>Tant que votre aptitude Sorcellerie innée est active, vous pouvez recourir à une option de Métamagie à chacun de vos tours sans dépenser de points de Sorcellerie.</p>', '', 56),
  (672, 'Bottes d’arme', '<p>Votre entraînement martial vous permet de recourir à la botte de trois types d’arme courante ou de guerre de votre choix. Chaque fois que vous terminez un Repos long, vous pouvez accomplir des exercices martiaux pour changer l’un de ces choix.</p><p>Lorsque vous atteignez certains niveaux de Guerrier, vous recevez la faculté de recourir à la botte d’autres types d’arme, comme indiqué à la colonne Bottes d’arme de la table « Aptitudes du Guerrier ».</p>', '', 50),
  (673, 'Second souffle', '<p>Vous disposez d’une réserve limitée d’endurance mentale et physique dans laquelle puiser. Par une action Bonus, vous pouvez y recourir pour récupérer des points de vie égaux à 1d10 + votre niveau de Guerrier.</p><p>Vous pouvez recourir deux fois à cette aptitude. Vous en regagnez une utilisation lorsque vous terminez un Repos court, et récupérez tout le quota en terminant un Repos long.</p><p>Lorsque vous atteignez certains niveaux de Guerrier, vous recevez d’autres utilisations de cette aptitude, comme indiqué à la colonne Second souffle de la table « Aptitudes du Guerrier ».</p>', '', 50),
  (674, 'Style de combat', '<p>Vous avez affûté vos techniques martiales et recevez le don de Style de combat de votre choix (cf. « Dons »). Défense est recommandé.</p><p>Chaque fois que vous recevez un niveau de Guerrier, vous pouvez remplacer le don choisi par un don différent de Style de combat.</p>', '', 50),
  (675, 'Fougue', '<p>Vous pouvez vous surpasser pendant quelques instants. À votre tour, vous pouvez entreprendre une action supplémentaire, hormis l’action Magie.</p><p>Une fois cette aptitude utilisée, vous devez terminer un Repos court ou long pour pouvoir y recourir de nouveau. À partir du niveau 17, vous pouvez y recourir deux fois avant un Repos, mais seulement une fois par tour.</p>', '', 50),
  (676, 'Sens tactique', '<p>Vous faites preuve de talent tactique, aussi bien sur le champ d’honneur qu’en dehors. Lorsque vous ratez un test de caractéristique, vous pouvez dépenser une utilisation de Second souffle pour forcer le destin. Plutôt que de récupérer des points de vie, vous lancez 1d10 pour en ajouter le résultat à votre test de caractéristique, ce qui peut le convertir en réussite. Si le test rate malgré tout, cette utilisation de Second souffle n’est pas dépensée.</p>', '', 50),
  (677, 'Sous-classe de Guerrier', '<p>Vous recevez la sous-classe de Guerrier de votre choix. La sous-classe Champion est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Guerrier. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel de Guerrier.</p>', '', 50),
  (678, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Guerrier 6, 8, 12, 14 et 16.</p>', '', 50),
  (679, 'Attaque supplémentaire', '<p>Vous pouvez attaquer deux fois au lieu d’une lorsque vous entreprenez l’action Attaque à votre tour.</p>', '', 50),
  (680, 'Décalage tactique', '<p>Chaque fois que vous activez votre Second souffle par une action Bonus, vous pouvez vous déplacer à concurrence de la moitié de votre Vitesse, sans provoquer d’attaques d’Opportunité.</p>', '', 50),
  (681, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Guerrier que vous avez choisie, correspondant à ce niveau.</p>', '', 50),
  (682, 'Botte tactique', '<p>Lorsque vous attaquez avec une arme dont vous pouvez exploiter la botte, vous pouvez remplacer cette botte par Poussée, Ralentissement ou Sape pour cette attaque.</p>', '', 50),
  (683, 'Inflexible', '<p>Si vous ratez un jet de sauvegarde, vous pouvez le rejouer avec un bonus égal à votre niveau de Guerrier. Dans ce cas, c’est forcément le nouveau jet qui s’applique et vous devez ensuite terminer un Repos long avant de pouvoir recourir de nouveau à cette aptitude.</p><p>Vous pouvez recourir deux fois à cette aptitude avant un Repos long à partir du niveau 13, puis trois fois à partir du niveau 17.</p>', '', 50),
  (684, 'Double attaque supplémentaire', '<p>Vous pouvez attaquer trois fois au lieu d’une lorsque vous entreprenez l’action Attaque à votre tour.</p>', '', 50),
  (685, 'Attaques avisées', '<p>Vous savez étudier la défense de l’adversaire au fil de vos attaques. Si vous effectuez un jet d’attaque contre une créature et que vous ratez, vous avez l’Avantage à votre prochain jet d’attaque contre elle intervenant avant la fin de votre tour suivant.</p>', '', 50),
  (686, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur de prouesse martiale est recommandé.</p>', '', 50),
  (687, 'Triple attaque supplémentaire', '<p>Vous pouvez attaquer quatre fois au lieu d’une lorsque vous entreprenez l’action Attaque à votre tour.</p>', '', 50),
  (688, 'Sorts', '<p>En tant qu’étudiant de la magie profane, vous avez appris à lancer des sorts. Reportez-vous à la section « Sorts » pour les règles d’incantation. Les informations ci-après expliquent comment utiliser ces règles avec les sorts de Magicien, qui figurent dans la liste Sorts de Magicien, plus loin dans le descriptif de la classe.</p><p>3 ———————— 4 2 ——————— 4 3 ——————— 4 3 2 —————— 4 3 3 —————— 4 3 3 1 ————— 4 3 3 2 ————— 4 3 3 3 1 ———— 4 3 3 3 2 ———— 4 3 3 3 2 1 ——— 4 3 3 3 2 1 ——— 4 3 3 3 2 1 1 —— 4 3 3 3 2 1 1 —— 4 3 3 3 2 1 1 1— 4 3 3 3 2 1 1 1— 433321111 433331111 433332111 433332211</p><p><b>Sorts mineurs.</b> Vous connaissez trois sorts mineurs de Magicien de votre choix. Lumière, main du mage et rayon de givre sont recommandés. Chaque fois que vous terminez un Repos long, vous pouvez remplacer l’un de vos sorts mineurs de cette aptitude par un autre sort mineur de Magicien de votre choix.</p><p>Lorsque vous atteignez les niveaux 4 et 10 de Magicien, vous apprenez un autre sort mineur de Magicien de votre choix, comme indiqué en colonne Sorts mineurs de la table « Aptitudes du Magicien ».</p><p><b>Grimoire.</b> Votre apprentissage de Magicien s’est conclu par la création d’un livre unique : votre grimoire. Cet objet de taille TP pèse 1,5 kg, contient 100 pages et ne peut être lu que par vous-même ou une tierce personne lançant le sort identification. Vous déterminez l’aspect et les matériaux employés dans la confection du grimoire : il peut s’agir d’un ouvrage doré à l’or fin comme d’un recueil de feuilles de vélin reliées par de la ficelle.</p><p>Le grimoire contient les sorts du 1er niveau et plus que vous connaissez. Il commence avec six sorts de Magicien du 1er niveau de votre choix. Armure du mage, détection de la magie, feuille morte, projectile magique, sommeil et vague tonnante sont recommandés.</p><p>Chaque fois que vous gagnez un niveau de Magicien après le premier, ajoutez deux sorts de Magicien de votre choix à votre grimoire. Chacun doit être d’un niveau pour lequel vous disposez d’emplacements de sort, comme indiqué sur la table « Aptitudes du Magicien ». Ces sorts sont l’aboutissement des recherches arcaniques que vous menez régulièrement. Emplacements de sort. La table « Aptitudes du</p><p>Magicien » vous indique le nombre d’emplacements de sort dont vous disposez pour lancer vos sorts du 1er niveau et supérieur. Vous récupérez tous les empla- cements dépensés en terminant un Repos long. Sorts préparés du 1er niveau et plus. Vous devez préparer la liste des sorts du 1er niveau et supérieur que cette aptitude vous permet de lancer. À cette fin, choisissez quatre sorts de votre grimoire. Ces sorts doivent être d’un niveau pour lequel vous disposez d’emplacements de sort.</p><p>Le nombre de sorts de votre liste augmente à mesure que vous recevez des niveaux de Magicien, comme l’indique la colonne Sorts préparés de la table « Aptitudes du Magicien ». Chaque fois que ce nombre augmente, choisissez des sorts de Magicien supplé- mentaires jusqu’à ce que le nombre de sorts de votre liste corresponde au nombre indiqué dans la table. Ces sorts doivent être d’un niveau pour lequel vous disposez d’emplacements de sort. Si, par exemple, vous êtes un Magicien de niveau 3, votre liste de sorts préparés peut inclure six sorts de Magicien du 1er ou</p><p>2e niveau choisis dans votre grimoire, répartis à votre guise.</p><p>Si une autre aptitude de Magicien vous octroie des sorts toujours préparés, ces sorts ne sont pas décomptés du nombre de sorts que vous pouvez préparer avec la présente aptitude, mais ils sont considérés pour vous comme des sorts de Magicien.</p><p><b>Modification des sorts préparés.</b> Chaque fois que vous terminez un Repos long, vous pouvez changer votre liste de sorts préparés en remplaçant des sorts par d’autres sorts de Magicien de votre grimoire.</p><p><b>Caractéristique d’incantation.</b> L’Intelligence est la caractéristique d’incantation de vos sorts de Magicien.</p><p><b>Focaliseur d’incantation.</b> Vous pouvez vous servir d’un focaliseur arcanique ou de votre grimoire comme focaliseur d’incantation de vos sorts de Magicien.</p>', '', 52),
  (689, 'Savoir rituel', '<p>Vous pouvez lancer comme rituel un sort qui porte la mention « rituel » et figure dans votre grimoire. Il n’est pas nécessaire d’avoir préparé ce sort, mais vous devez le lire depuis votre grimoire pour lancer un sort ainsi.</p>', '', 52),
  (690, 'Restauration magique', '<p>Vous pouvez récupérer une partie de votre énergie magique en étudiant votre grimoire. En terminant un Repos court, désignez si vous le souhaitez les emplacements de sort dépensés que vous souhaitez récupérer.</p><p>Étoffer et remplacer son grimoire</p><p>Les sorts que vous ajoutez à votre grimoire à mesure que vous gagnez des niveaux reflètent vos recherches magiques en cours, mais vous pourriez aussi trouver d’autres sorts à incorporer au grimoire au fil de vos aventures. Vous pourriez par exemple découvrir un sort de Magicien inscrit sur un parchemin de sort, et le recopier dans votre grimoire.</p><p><b>Recopier un sort.</b> Chaque fois que vous trouvez un sort de Magicien du 1er niveau ou plus, vous pouvez le recopier dans votre grimoire s’il est d’un niveau que vous pouvez préparer et si vous disposez du temps nécessaire. Cette opération nécessite 2 heures et 50 po par niveau du sort. Par la suite, vous pouvez le préparer comme les autres sorts inscrits dans votre grimoire.</p><p><b>Faire une copie du grimoire.</b> Vous pouvez copier un sort de votre grimoire dans un autre. La procédure est la même que pour recopier un nouveau sort dans votre grimoire mais elle s’avère plus rapide, car vous savez déjà lancer ce sort. 1 heure et 10 po par niveau du sort recopié suffisent.</p><p>Si vous perdez votre grimoire, vous pouvez recourir à cette même opération pour retranscrire les sorts de Magicien que vous avez préparés dans un nouveau grimoire. Pour le reste, il vous faudra trouver de nouveaux sorts (ou remettre la main sur ceux que vous avez perdus). C’est pourquoi de nombreux Magiciens conservent un grimoire de secours.</p><p>La somme des niveaux de ces emplacements ne doit pas excéder la moitié de votre niveau de Magicien (arrondie au supérieur), et aucun de ces emplacements de sort ne doit être du 6e niveau ou plus. En tant que Magicien de niveau 4, par exemple, vous pouvez récupérer jusqu’à deux niveaux d’emplacements de sort, soit un emplacement de sort du 2e niveau ou deux emplacements de sort du 1er niveau.</p><p>Une fois cette aptitude utilisée, vous devez terminer un Repos long pour pouvoir y recourir de nouveau.</p>', '', 52),
  (691, 'Érudition', '<p>Tout en étudiant la magie, vous vous êtes spécialisé dans un autre domaine. Choisissez l’une des compétences ci-après dont vous avez la maîtrise : Arcanes, Histoire, Intuition, Investigation, Médecine, Nature ou Religion. Vous avez l’Expertise dans la compétence choisie.</p>', '', 52),
  (692, 'Sous-classe de Magicien', '<p>Vous recevez la sous-classe de Magicien de votre choix. La sous-classe Évocateur est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Magicien. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel de Magicien.</p>', '', 52),
  (693, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Magicien 8, 12 et 16.</p>', '', 52),
  (694, 'Mémorisation de sort', '<p>Chaque fois que vous terminez un Repos court, vous pouvez étudier votre grimoire et remplacer l’un des sorts de Magicien du 1er niveau ou supérieur préparé dans le cadre de l’aptitude Sorts par un autre sort du 1er niveau ou plus tiré du grimoire.</p>', '', 52),
  (695, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Magicien que vous avez choisie, correspondant à ce niveau.</p>', '', 52),
  (696, 'Maîtrise des sorts', '<p>Vous avez atteint une telle maîtrise de certains sorts que vous pouvez désormais les lancer à volonté. Choisissez un sort du 1er niveau et un sort du 2e niveau dans votre grimoire, dont le temps d’incantation est d’une action. Ces sorts sont considérés comme toujours préparés pour vous, et vous pouvez les lancer à leur niveau le plus bas sans dépenser d’emplacement de sort. Si vous souhaitez les lancer à un niveau supérieur, vous devez toutefois dépenser un emplacement de sort.</p><p>Chaque fois que vous terminez un Repos long, vous pouvez étudier votre grimoire et remplacer l’un de ces sorts par un sort conforme du même niveau tiré du grimoire.</p>', '', 52),
  (697, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur de mémoire magique est recommandé.</p>', '', 52),
  (698, 'Sorts de prédilection', '<p>Choisissez deux sorts de Magicien du 3e niveau de votre grimoire comme sorts de prédilection. Ces sorts sont considérés comme toujours préparés pour vous, et vous pouvez les lancer une fois chacun au 3e niveau sans dépenser d’emplacement de sort. Après cela, vous devez terminer un Repos court ou long avant de pouvoir les relancer sans emplacement. Si vous souhaitez les lancer à un niveau supérieur, vous devez toutefois dépenser un emplacement de sort.</p>', '', 52),
  (699, 'Arts martiaux', '<p>Votre pratique des arts martiaux vous permet de maîtriser des styles de combat axés sur vos attaques à mains nues et vos armes de Moine, à savoir :</p><ul><li>Les armes courantes de corps à corps</li><li>Les armes de guerre de corps à corps dotées de la propriété Légère</li></ul><p>Tant que vous combattez à mains nues ou avec des armes de Moine et que vous ne portez ni armure ni bouclier, vous recevez les bénéfices suivants.</p><p><b>Attaque à mains nues supplémentaire.</b> Vous pouvez effectuer une attaque à mains nues par une action Bonus.</p><p><b>Dé d’Arts martiaux.</b> Vous pouvez lancer 1d6 à la place des dégâts normaux de votre attaque à mains nues et de vos armes de Moine. Ce dé évolue à mesure que vous gagnez des niveaux de Moine, comme indiqué dans la colonne Arts martiaux de la table « Aptitudes du Moine ».</p><p><b>Attaques lestes.</b> Vous pouvez appliquer votre modificateur de Dextérité au lieu de celui de Force pour les jets d’attaque et de dégâts si vous attaquez à mains nues ou avec des armes de Moine. De plus, lorsque vous recourez à l’option Bousculade ou Lutte de votre attaque à mains nues, vous pouvez appliquer votre modificateur de Dextérité au lieu de celui de Force pour en déterminer le DD de sauvegarde.</p>', '', 57),
  (700, 'Défense sans armure', '<p>Tant que vous ne portez ni armure ni bouclier, votre classe d’armure de base est égale à 10 + vos modificateurs de Dextérité et de Sagesse.</p>', '', 57),
  (701, 'Déplacement sans armure', '<p>Votre Vitesse augmente de 3 m tant que vous ne portez ni armure ni bouclier. Ce bonus évolue à mesure que vous gagnez des niveaux de Moine, comme indiqué dans la table « Aptitudes du Moine ».</p>', '', 57),
  (702, 'Credo du Moine', '<p>Votre discipline et votre formation martiale vous permettent de puiser dans la source d’énergie extraordinaire qui est en vous. Cette énergie est représentée par les points de Credo. Votre niveau de Moine détermine le nombre de points dont vous disposez, comme indiqué dans la colonne Points de Credo de la table Aptitudes du Moine.</p><p>Vous pouvez dépenser ces points pour améliorer ou alimenter certaines aptitudes de Moine. Vous débutez en connaissant trois de ces aptitudes : Déluge de coups, Patience défensive et Porté par le vent, détaillées chacune ci-après.</p><p>Lorsque vous dépensez un point de Credo, il n’est plus disponible jusqu’à ce que vous terminiez un Repos court ou long, à l’issue duquel vous récupérez tous vos points dépensés.</p><p>Certaines aptitudes basées sur les points de Credo imposent un jet de sauvegarde à votre cible. Le DD de sauvegarde est égal à 8 plus votre modificateur de Sagesse et votre bonus de maîtrise.</p><p><b>Déluge de coups.</b> Vous pouvez dépenser 1 point de Credo pour effectuer deux attaques à mains nues par une action Bonus.</p><p><b>Patience défensive.</b> Vous pouvez entreprendre l’action Désengagement par une action Bonus. Vous avez aussi la possibilité, par une action Bonus et la dépense de 1 point de Credo, d’entreprendre à la fois l’action Désengagement et l’action Esquive.</p><p><b>Porté par le vent.</b> Vous pouvez entreprendre l’action Pointe par une action Bonus. Vous avez aussi la possibilité, par une action Bonus et la dépense de 1 point de Credo, d’entreprendre à la fois l’action Désengagement et l’action Pointe, et de doubler votre distance de saut pour ce tour.</p>', '', 57),
  (703, 'Métabolisme surnaturel', '<p>Lorsque vous jouez l’Initiative, vous pouvez récupérer tous vos points de Credo dépensés. Ce faisant, lancez votre dé d’Arts martiaux et récupérez autant de points de vie que votre niveau de Moine plus le résultat du dé.</p><p>Une fois que vous avez utilisé cette aptitude, vous devez terminer un Repos long pour pouvoir y recourir de nouveau.</p>', '', 57),
  (704, 'Déviation d’assaut', '<p>Lorsqu’un jet d’attaque vous touche et que ses dégâts incluent des dégâts contondants, perforants ou tranchants, vous pouvez jouer votre Réaction pour réduire contre vous les dégâts totaux de l’attaque. La réduction est égale à 1d10 plus votre modificateur de Dextérité et votre niveau de Moine.</p><p>Si vous réduisez ainsi les dégâts à 0, vous pouvez dépenser 1 point de Credo pour dévier une partie de l’impact à votre guise. Dans ce cas, choisissez une créature que vous voyez dans un rayon de 1,50 m si l’attaque était de corps à corps, ou une créature que vous voyez dans un rayon de 18 m et qui ne bénéficie pas d’un Abri total si l’attaque était à distance. Cette créature doit réussir un jet de sauvegarde de Dextérité sous peine de subir des dégâts égaux à deux jets de votre dé d’Arts martiaux plus votre modificateur de Dextérité. Les dégâts sont du même type que ceux infligés par l’attaque.</p>', '', 57),
  (705, 'Sous-classe de Moine', '<p>Vous recevez la sous-classe de Moine de votre choix. La sous-classe Credo de la Paume est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Moine. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel de Moine.</p>', '', 57),
  (706, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Moine 8, 12 et 16.</p>', '', 57),
  (707, 'Chute ralentie', '<p>Vous pouvez jouer votre Réaction pour réduire les dégâts de chute que vous subissez d’un montant égal au quintuple de votre niveau de Moine.</p>', '', 57),
  (708, 'Attaque supplémentaire', '<p>Vous pouvez attaquer deux fois au lieu d’une lorsque vous entreprenez l’action Attaque à votre tour.</p>', '', 57),
  (709, 'Frappe étourdissante', '<p>Une fois par tour, lorsque vous touchez une créature avec une arme de Moine ou à mains nues, vous pouvez dépenser 1 point de Credo pour tenter de placer une frappe étourdissante. La cible effectue un jet de sauvegarde de Constitution. En cas d’échec, la cible subit l’état Étourdi jusqu’au début de votre tour suivant. En cas de réussite, la Vitesse de la cible est réduite de moitié jusqu’au début de votre tour suivant et le prochain jet d’attaque contre la cible dans cet intervalle a l’Avantage.</p>', '', 57),
  (710, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Moine que vous avez choisie, correspondant à ce niveau.</p>', '', 57),
  (711, 'Frappes renforcées', '<p>Chaque fois que vous infligez des dégâts avec une attaque à mains nues, ceux-ci sont à votre convenance des dégâts de force ou du type normal de l’attaque.</p>', '', 57),
  (712, 'Esquive totale', '<p>Quand vous êtes soumis à un effet qui vous permet d’effectuer un jet de sauvegarde de Dextérité pour réduire les dégâts de moitié, vous ne subissez aucun dégât en cas de sauvegarde réussie, et seulement la moitié en cas d’échec.</p><p>Vous ne bénéficiez pas de cette aptitude si vous subissez l’état Neutralisé.</p>', '', 57),
  (713, 'Mouvement acrobatique', '<p>Tant que vous ne portez ni armure ni bouclier, vous recevez la capacité de vous déplacer à votre tour le long de surfaces verticales et à travers des liquides sans tomber.</p>', '', 57),
  (714, 'Autosubsistance', '<p>Par la seule force de l’esprit, vous pouvez vous débarrasser de l’un des états suivants à la fin de chacun de vos tours : Charmé, Effrayé ou Empoisonné.</p><p>De plus, vous passer de nourriture et d’eau ne vous impose pas de niveaux d’Épuisement.</p>', '', 57),
  (715, 'Credo accru', '<p>Déluge de coups, Patience défensive et Porté par le vent reçoivent respectivement les bénéfices suivants.</p><p><b>Déluge de coups.</b> Vous pouvez dépenser 1 point de Credo pour recourir à Déluge de coups et effectuer trois attaques à mains nues au lieu de deux.</p><p><b>Patience défensive.</b> Lorsque vous dépensez un point de Credo pour recourir à Patience défensive, vous recevez des points de vie temporaires égaux à deux jets de votre dé d’Arts martiaux.</p><p><b>Porté par le vent.</b> Lorsque vous dépensez un point de Credo pour recourir à Porté par le vent, vous pouvez choisir une créature consentante dans un rayon de 1,50 m, de taille G ou inférieure. Vous déplacez la créature avec vous jusqu’à la fin de votre tour. Le déplacement de cette créature ne provoque pas d’attaques d’Opportunité.</p>', '', 57),
  (716, 'Parade énergétique', '<p>Vous pouvez désormais recourir à l’aptitude Déviation d’assaut contre les attaques qui infligent tout type de dégâts, et non plus seulement contondants, perforants ou tranchants.</p>', '', 57),
  (717, 'Survivant discipliné', '<p>Votre discipline physique et mentale vous octroie la maîtrise de tous les jets de sauvegarde.</p><p>De plus, chaque fois que vous effectuez un jet de sauvegarde et ratez, vous pouvez dépenser 1 point de Credo pour le rejouer et conserver le nouveau jet.</p>', '', 57),
  (718, 'Credo parachevé', '<p>Lorsque vous jouez l’Initiative, que vous ne recourez pas à Métabolisme surnaturel et qu’il vous reste moins de 4 points de Credo, vous en récupérez jusqu’à en avoir 4.</p>', '', 57),
  (719, 'Défense supérieure', '<p>Au début de votre tour, vous pouvez dépenser 3 points de Credo pour consolider votre corps pendant 1 minute (l’effet prend fin si vous subissez l’état Neutralisé). Durant cet intervalle, vous bénéficiez de la Résistance à tous les dégâts hormis ceux de force.</p>', '', 57),
  (720, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur d’attaque irrésistible est recommandé.</p>', '', 57),
  (721, 'Esprit et corps', '<p>Le développement de votre corps et de votre esprit atteint de nouveaux sommets. Vos valeurs de Dextérité et Sagesse augmentent de 4, jusqu’à un maximum de 25.</p>', '', 57),
  (722, 'Manifestations occultes', '<p>Vos recherches ésotériques vous ont permis de dénicher des Manifestations occultes, fragments de savoir interdit qui vous octroient divers pouvoirs magiques. Vous recevez une manifestation de votre choix, comme Pacte du grimoire. Ces manifestations sont décrites en section « Options de Manifestation occulte », plus loin dans le descriptif de cette classe.</p><p><b>Prérequis.</b> Si une manifestation s’accompagne d’un prérequis, vous devez le remplir pour pouvoir l’apprendre. Si, par exemple, une manifestation nécessite que vous soyez un Occultiste de niveau 5 ou supérieur, vous ne pourrez choisir cette manifestation qu’une fois atteint le niveau 5 dans cette classe.</p><p><b>Remplacer et recevoir des manifestations.</b> Chaque fois que vous gagnez un niveau d’Occultiste, vous pouvez remplacer l’une de vos manifestations par une autre pour laquelle vous remplissez les conditions. Vous ne pouvez pas remplacer une manifestation si elle est un prérequis à une autre manifestation dont vous disposez.</p><p>Vous en apprendrez d’autres que vous choisirez à plus haut niveau, comme le montre la colonne Manifestations de la table « Aptitudes de l’Occultiste ».</p><p>Vous ne pouvez pas choisir la même manifestation plus d’une fois, sauf si sa description précise le contraire.</p>', '', 58),
  (723, 'Magie de pacte', '<p>Lors d’une cérémonie impie, vous avez scellé un pacte avec une mystérieuse entité afin de recevoir des pouvoirs magiques. Si l’entité est une voix ténébreuse dont l’identité reste obscure, la faveur qu’elle vous octroie est on ne peut plus tangible : l’aptitude à lancer des sorts. Reportez-vous à la section « Sorts » pour les règles d’incantation. Les informations ci-après expliquent comment utiliser ces règles avec les sorts d’Occultiste, qui figurent dans la liste Sorts d’Occultiste, plus loin dans le descriptif de la classe.</p><p><b>Sorts mineurs.</b> Vous connaissez deux sorts mineurs d’Occultiste de votre choix. Décharge occulte et prestidigitation sont recommandés. Chaque fois que vous gagnez un niveau d’Occultiste, vous pouvez remplacer l’un de vos sorts mineurs de cette aptitude par un autre sort mineur d’Occultiste de votre choix.</p><p>Lorsque vous atteignez les niveaux 4 et 10 d’Occultiste, vous apprenez un autre sort mineur d’Occultiste de votre choix, comme indiqué en colonne Sorts mineurs de la table Aptitudes de l’Occultiste.</p><p><b>Emplacements de sort.</b> La table « Aptitudes de l’Occultiste » vous indique le nombre d’emplacements de sort dont vous disposez pour lancer vos sorts d’Occultiste du 1er au 5e niveau. La table indique en outre le niveau de ces emplacements, qui sont tous du même niveau. Vous récupérez tous les emplacements de sort de Magie de pacte dépensés en terminant un Repos court ou long.</p><p>En tant qu’Occultiste de niveau 5, par exemple, vous disposez de deux emplacements de sorts du 3e niveau. Pour lancer le sort du 1er niveau charme-personne, vous devez dépenser l’un de ces emplacements et vous le lancez comme un sort du 3e niveau.</p><p><b>Sorts préparés du 1er niveau et plus.</b> Vous devez préparer la liste des sorts du 1er niveau et supérieur que cette aptitude vous permet de lancer. Pour commencer, choisissez deux sorts du 1er niveau de l’Occultiste. Charme-personne et maléfice sont recommandés.</p><p>Le nombre de sorts de votre liste augmente à mesure que vous recevez des niveaux d’Occultiste, comme l’indique la colonne Sorts préparés de la table « Aptitudes de l’Occultiste ». Chaque fois que ce nombre augmente, choisissez des sorts d’Occultiste supplémentaires jusqu’à ce que le nombre de sorts de votre liste corresponde au nombre indiqué dans la table « Aptitudes de l’Occultiste ». Les sorts choisis ne doivent pas être d’un niveau supérieur à ce qui figure dans la colonne Niveau des emplacements pour votre niveau. Lorsque vous atteignez le niveau 6, par exemple, vous apprenez un nouveau sort d’Occultiste, qui peut être du 1er au 3e niveau.</p><p>Si une autre aptitude d’Occultiste vous octroie des sorts toujours préparés, ces sorts ne sont pas décomptés du nombre de sorts que vous pouvez préparer avec la présente aptitude, mais ils sont considérés pour vous comme des sorts d’Occultiste.</p><p><b>Modification des sorts préparés.</b> Chaque fois que vous gagnez un niveau d’Occultiste, vous pouvez remplacer un sort de votre liste par un autre sort d’Occultiste de niveau conforme.</p><p><b>Caractéristique d’incantation.</b> Le Charisme est la caractéristique d’incantation de vos sorts d’Occultiste.</p><p><b>Focaliseur d’incantation.</b> Vous pouvez vous servir d’un focaliseur arcanique comme focaliseur d’incantation de vos sorts d’Occultiste.</p>', '', 58),
  (724, 'Rouerie magique', '<p>Vous pouvez accomplir un rite ésotérique qui dure 1 minute. À la fin de ce délai, vous regagnez des emplacements de sorts de Magie de pacte dépensés, à concurrence de la moitié du maximum (arrondie au supérieur). Une fois cette aptitude utilisée, vous devez terminer un Repos long pour pouvoir y recourir de nouveau.</p>', '', 58),
  (725, 'Sous-classe d’Occultiste', '<p>Vous recevez la sous-classe d’Occultiste de votre choix. La sous-classe Protecteur Fiélon est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux d’Occultiste. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel d’Occultiste.</p>', '', 58),
  (726, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux d’Occultiste 8, 12 et 16.</p>', '', 58),
  (727, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Occultiste que vous avez choisie, correspondant à ce niveau.</p>', '', 58),
  (728, 'Communication avec le protecteur', '<p>Dans le passé, vous contactiez généralement votre protecteur par le biais d’intermédiaires. Vous pouvez désormais communiquer directement avec lui ; le sort contact avec les plans est considéré comme toujours préparé pour vous. Cette aptitude vous permet de lancer le sort sans dépenser d’emplacement de sort pour contacter votre protecteur, et vous réussissez automatiquement le jet de sauvegarde du sort.</p><p>Une fois un sort lancé par ce biais, vous devez terminer un Repos long avant de pouvoir refaire ainsi.</p>', '', 58),
  (729, 'Arcanum mystique', '<p>Votre protecteur vous octroie un secret magique appelé arcanum. Choisissez un sort d’Occultiste du 6e niveau pour cet arcanum.</p><p>Vous pouvez lancer ce sort d’arcanum sans dépenser d’emplacement de sort, sachant que vous devez ensuite terminer un Repos long avant de pouvoir le relancer par ce biais.</p><p>Comme indiqué dans la table « Aptitudes de l’Occultiste », vous recevez un autre sort d’Occultiste de votre choix qui peut être lancé de cette manière lorsque vous atteignez les niveaux 13 (sort du 7e niveau), 15 (sort du 8e niveau) et 17 (sort du 9e niveau) d’Occultiste. Vous récupérez toutes vos utilisations d’Arcanum mystique en terminant un Repos long.</p><p>Chaque fois que vous gagnez un niveau d’Occultiste, vous pouvez remplacer l’un de vos sorts d’arcanum par un autre sort d’Occultiste du même niveau.</p>', '', 58),
  (730, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur du destin est recommandé.</p>', '', 58),
  (731, 'Maître de l’occulte', '<p>Lorsque vous utilisez votre aptitude Rouerie magique, vous récupérez tous les emplacements de sort dépensés de Magie de pacte.</p>', '', 58),
  (732, 'Bottes d’arme', '<p>Votre entraînement martial vous permet de recourir à la propriété Botte de deux types d’arme de votre choix parmi celles dont vous avez la maîtrise, par exemple l’épée longue et la javeline.</p><p>Chaque fois que vous terminez un Repos long, vous pouvez changer le type d’arme que vous avez choisi. Vous pourriez par exemple décider d’opter pour les propriétés Bottes de la hallebarde et du fléau d’armes.</p>', '', 59),
  (733, 'Imposition des mains', '<p>Votre contact béni peut soigner les blessures. Vous disposez d’une réserve de puissance curatrice qui se reconstitue lorsque vous terminez un Repos long. Cette réserve vous permet de restituer un total de points de vie égal à cinq fois votre niveau de Paladin.</p><p>Par une action Bonus, vous pouvez puiser tout ou partie de cette réserve et, d’un simple contact, restituer autant de points de vie à une créature (qui peut être vous-même) à concurrence du maximum de cette réserve. destrier +3 Aura de protection +3 Aptitude de sous-classe +3 Amélioration de caractéristique +4 Abjuration d’ennemis +4 Aura de courage +4 Frappes radiantes +4 Amélioration de caractéristique +5 — +5 Toucher réparateur +5 Aptitude de sous-classe +5 Amélioration de caractéristique +6 — +6 Aura étendue +6 Faveur épique +6 Aptitude de sous-classe</p><p>Conduit divin</p><p>—</p><p>Sorts préparés</p><p>—Emplacements par niveau de sort—</p><p>————</p><p>—</p><p>————</p><p>————</p><p>————</p><p>2 ———</p><p>2 ———</p><p>3 ———</p><p>3 ———</p><p>3 2 ——</p><p>3 2 ——</p><p>3 3 ——</p><p>3 3 ——</p><p>3 3 1—</p><p>3 3 1—</p><p>3 3 2—</p><p>3 3 2—</p><p>3331</p><p>3331</p><p>3332</p><p>3332</p><p>Vous pouvez également dépenser 5 points de vie de la réserve de puissance curatrice pour supprimer l’état Empoisonné affectant la créature ; ces points ne font pas récupérer de pv à la créature.</p>', '', 59),
  (734, 'Sorts', '<p>Vous avez appris à lancer des sorts grâce à la prière et à la méditation. Reportez-vous à la section « Sorts » pour les règles d’incantation. Les informations ci-après expliquent comment utiliser ces règles avec les sorts de Paladin, qui figurent dans la liste Sorts de Paladin, plus loin dans le descriptif de la classe.</p><p><b>Emplacements de sort.</b> La table « Aptitudes du Paladin » vous indique le nombre d’emplacements de sort dont vous disposez pour lancer vos sorts du 1er niveau et supérieur. Vous récupérez tous les emplacements dépensés en terminant un Repos long.</p><p><b>Sorts préparés du 1er niveau et plus.</b> Vous devez préparer la liste des sorts du 1er niveau et supérieur que cette aptitude vous permet de lancer. Pour commencer, choisissez deux sorts du 1er niveau du Paladin. Héroïsme et châtiment de fournaise sont recommandés.</p><p>Le nombre de sorts de votre liste augmente à mesure que vous recevez des niveaux de Paladin, comme l’indique la colonne Sorts préparés de la table « Aptitudes du Paladin ». Chaque fois que ce nombre augmente, choisissez des sorts de Paladin supplémentaires jusqu’à ce que le nombre de sorts de votre liste corresponde au nombre indiqué dans la table « Aptitudes du Paladin ». Ces sorts doivent être d’un niveau pour lequel vous disposez d’emplacements de sort. Si, par exemple, vous êtes un Paladin de niveau 5, votre liste de sorts préparés peut inclure six sorts de Paladin du 1er ou 2e niveau, répartis à votre guise.</p><p>Si une autre aptitude de Paladin vous octroie des sorts toujours préparés, ces sorts ne sont pas décomptés du nombre de sorts que vous pouvez préparer avec la présente aptitude, mais ils sont considérés pour vous comme des sorts de Paladin.</p><p><b>Modification des sorts préparés.</b> Chaque fois que vous terminez un Repos long, vous pouvez remplacer l’un des sorts de votre liste par un autre sort de Paladin pour lequel vous disposez d’emplacements de sort.</p><p><b>Caractéristique d’incantation.</b> Le Charisme est la caractéristique d’incantation de vos sorts de paladin.</p><p><b>Focaliseur d’incantation.</b> Vous pouvez vous servir d’un symbole sacré comme focaliseur d’incantation de vos sorts de paladin.</p>', '', 59),
  (735, 'Châtiment de paladin', '<p>Le sort châtiment divin est toujours préparé pour vous. Vous pouvez en outre lancer ce sort sans dépenser d’emplacement de sort, sachant que vous devez ensuite terminer un Repos long avant de pouvoir le relancer par ce biais.</p>', '', 59),
  (736, 'Style de combat', '<p>Vous recevez le don de Style de combat de votre choix (cf. « Dons » pour la liste des dons). Au lieu de choisir l’un de ces dons, vous pouvez choisir l’option ci-dessous.</p><p><b>Combattant béni.</b> Vous apprenez deux sorts mineurs de Clerc de votre choix (la liste des sorts de Clerc est consultable dans la section de cette classe). Assistance et flamme sacrée sont recommandés. Les sorts mineurs choisis sont considérés pour vous comme des sorts de Paladin, et le Charisme est la caractéristique d’incantation associée. Chaque fois que vous gagnez un niveau de Paladin, vous pouvez remplacer l’un de ces sorts mineurs par un autre sort mineur de Clerc.</p>', '', 59),
  (737, 'Conduit divin', '<p>Vous pouvez canaliser l’énergie divine directement depuis les Plans Extérieurs afin de produire des effets magiques. Vous débutez avec un seul de ces effets : Perception divine, décrite ci-après. D’autres aptitudes de Paladin octroient des effets supplémentaires</p><p>Rompre votre serment</p><p>Les paladins ont beau s’efforcer de respecter une éthique très exigeante, même le plus dévoué d’entre eux reste un être faillible. Il arrive qu’un Paladin transgresse son serment.</p><p>Un Paladin qui a rompu un vœu cherche généralement à obtenir l’absolution, en passant une nuit à veiller en signe de pénitence ou en se pliant à un jeûne expiatoire. Après un tel rite de pardon, ce Paladin prend un nouveau départ.</p><p>Si votre Paladin viole son serment sans chercher à faire amende honorable, parlez-en à votre MJ. Votre Paladin devrait probablement choisir une sousclasse plus appropriée, voire abandonner la classe et en adopter une autre. de Conduit divin. Chaque fois que vous recourez au Conduit divin de cette classe, vous choisissez l’effet associé que vous souhaitez générer.</p><p>Vous pouvez utiliser deux fois le Conduit divin de cette classe. Vous en regagnez une utilisation lorsque vous terminez un Repos court, et récupérez toutes ses utilisations en terminant un Repos long. Vous recevez une utilisation supplémentaire en atteignant le niveau 11 de Paladin.</p><p>Si un effet de Conduit divin entraîne un jet de sauvegarde, le DD est égal au DD de sauvegarde des sorts de l’aptitude Sorts de cette classe.</p><p><b>Perception divine.</b> Par une action Bonus, vous ouvrez votre conscience à la présence de créatures de type Céleste, Fiélon et Mort-vivant. Pendant 10 minutes ou jusqu’à ce que vous subissiez l’état Neutralisé, vous savez où se trouve toute créature des types précités dans un rayon de 18 m, et connaissez son type de créature. Dans ce même rayon, vous détectez en outre la présence de tout lieu ou objet qui a été consacré ou profané, comme avec le sort sanctification.</p>', '', 59),
  (738, 'Sous-classe de Paladin', '<p>Vous recevez la sous-classe de Paladin de votre choix. La sous-classe Serment de Dévotion est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Paladin. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel de Paladin.</p>', '', 59),
  (739, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Paladin 8, 12 et 16.</p>', '', 59),
  (740, 'Attaque supplémentaire', '<p>Vous pouvez attaquer deux fois au lieu d’une lorsque vous entreprenez l’action Attaque à votre tour.</p>', '', 59),
  (741, 'Fidèle destrier', '<p>Vous pouvez faire appel à un destrier d’outre-monde. Le sort appel de destrier est toujours considéré comme préparé pour vous.</p><p>Vous pouvez en outre le lancer une fois sans dépenser d’emplacement de sort et récupérez cette faculté en terminant un Repos long.</p>', '', 59),
  (742, 'Aura de protection', '<p>Vous diffusez une aura protectrice indiscernable sous forme d’Émanation dans un rayon de 3 m. Cette aura est inactive tant que vous subissez l’état Neutralisé.</p><p>Vous-même et vos alliés dans l’aura recevez un bonus aux jets de sauvegarde égal à votre modificateur de Charisme (bonus minimum de +1).</p><p>Si un autre Paladin est présent, une créature ne peut bénéficier que d’une seule Aura de protection à la fois ; la créature choisit l’aura dont elle bénéficie.</p>', '', 59),
  (743, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Paladin que vous avez choisie, correspondant à ce niveau.</p>', '', 59),
  (744, 'Abjuration d’ennemis', '<p>Au prix de l’action Magie, vous pouvez dépenser une utilisation de Conduit divin de cette classe afin de vous faire craindre de vos ennemis. Tout en brandissant votre symbole sacré ou votre arme, vous pouvez cibler un nombre de créatures égal à votre modificateur de Charisme (minimum d’une créature) que vous voyez dans un rayon de 18 m. Chaque cible doit réussir un jet de sauvegarde de Sagesse sous peine de subir l’état Effrayé pendant 1 minute ou jusqu’à ce qu’elle subisse des dégâts. Tant qu’elle subit cet état Effrayé, la cible ne peut faire qu’une seule des choses suivantes à son tour : se déplacer, entreprendre une action ou une action Bonus.</p>', '', 59),
  (745, 'Aura de courage', '<p>Vous-même et vos alliés jouissez de l’Immunité contre l’état Effrayé au sein de votre Aura de protection. Si un allié Effrayé pénètre dans l’aura, cet état est réprimé sur cet allié tant qu’il s’y trouve.</p>', '', 59),
  (746, 'Frappes radiantes', '<p>Vos frappes s’accompagnent désormais de puissance surnaturelle. Quand vous touchez une cible avec un jet d’attaque avec une arme de corps à corps ou à mains nues, cette cible subit 1d8 dégâts radiants supplémentaires.</p>', '', 59),
  (747, 'Toucher réparateur', '<p>Lorsque vous utilisez Imposition des mains sur une créature, vous pouvez également lui retirer un ou plusieurs des états ci-après : Assourdi, Aveuglé, Charmé, Effrayé, Étourdi ou Paralysé. Vous devez dépenser 5 points de vie de la réserve de soins d’Imposition des mains pour chacun des états que vous supprimez ; ces points ne rendent pas de pv à la créature.</p>', '', 59),
  (748, 'Aura étendue', '<p>Votre Aura de protection est désormais une Émanation de 9 m.</p>', '', 59),
  (749, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur de Vision lucide est recommandé.</p>', '', 59),
  (750, 'Sorts', '<p>Vous avez appris à lancer des sorts en canalisant l’essence magique de la nature. Reportez-vous à la section « Sorts » pour les règles d’incantation. Les informations ci-après expliquent comment utiliser ces règles avec les sorts de Rôdeur, qui figurent dans la liste Sorts de Rôdeur, plus loin dans le descriptif de la classe.</p><p><b>Emplacements de sort.</b> La table « Aptitudes du Rôdeur » vous indique le nombre d’emplacements de sort dont vous disposez pour lancer vos sorts du 1er niveau et supérieur. Vous récupérez tous les emplacements dépensés en terminant un Repos long.</p><p><b>Sorts préparés du 1er niveau et plus.</b> Vous devez préparer la liste des sorts du 1er niveau et supérieur que cette aptitude vous permet de lancer. Pour commencer, choisissez deux sorts du 1er niveau du Rôdeur. Frappe piégeuse et soins sont recommandés.</p><p>Le nombre de sorts de votre liste augmente à mesure que vous recevez des niveaux de Rôdeur, comme l’indique la colonne Sorts préparés de la table « Aptitudes du Rôdeur ». Chaque fois que ce nombre augmente, choisissez des sorts de Rôdeur supplémentaires jusqu’à ce que le nombre de sorts de votre liste corresponde au nombre indiqué dans la table « Aptitudes du Rôdeur ». Ces sorts doivent être d’un niveau pour lequel vous disposez d’emplacements de sort. Si, par exemple, vous êtes un Rôdeur de niveau 5, votre liste de sorts préparés peut inclure six sorts de Rôdeur du 1er ou 2e niveau, répartis à votre guise.</p><p>Si une autre aptitude de Rôdeur vous octroie des sorts toujours préparés, ces sorts ne sont pas décomptés du nombre de sorts que vous pouvez préparer avec la présente aptitude, mais ils sont considérés pour vous comme des sorts de Rôdeur.</p><p><b>Modification des sorts préparés.</b> Chaque fois que vous terminez un Repos long, vous pouvez remplacer l’un des sorts de votre liste par un autre sort de Rôdeur pour lequel vous disposez d’emplacements de sort.</p><p><b>Caractéristique d’incantation.</b> La Sagesse est la caractéristique d’incantation de vos sorts de Rôdeur.</p><p><b>Focaliseur d’incantation.</b> Vous pouvez vous servir d’un focaliseur druidique comme focaliseur d’incantation de vos sorts de Rôdeur.</p>', '', 60),
  (751, 'Ennemi juré', '<p>Le sort marque du chasseur est toujours préparé pour vous. Vous pouvez le lancer deux fois sans dépenser d’emplacement de sort, et vous récupérez toutes les utilisations de cette aptitude en terminant un Repos long.</p><p>Le nombre de fois où vous pouvez lancer ce sort sans dépenser d’emplacement de sort augmente à mesure que vous gagnez des niveaux de Rôdeur, comme spécifié dans la colonne Ennemi juré de la table « Aptitudes du Rôdeur ».</p>', '', 60),
  (752, 'Bottes d’arme', '<p>Votre entraînement martial vous permet de recourir à la propriété Botte de deux types d’arme de votre choix parmi celles dont vous avez la maîtrise, par exemple l’arc long et l’épée courte.</p><p>Chaque fois que vous terminez un Repos long, vous pouvez changer le type d’arme que vous avez choisi. Vous pourriez par exemple décider d’opter pour les propriétés Bottes du cimeterre et de l’épée longue.</p>', '', 60),
  (753, 'Fin explorateur', '<p>Vos voyages incessants vous ont permis de recevoir les bénéfices suivants.</p><p><b>Expertise.</b> Choisissez l’une de vos maîtrises de compétence ne bénéficiant pas de l’Expertise. Vous recevez l’Expertise dans cette compétence.</p><p><b>Langues.</b> Vous connaissez deux langues de votre choix dans les tables des langues de la section « Création de personnage ».</p>', '', 60),
  (754, 'Style de combat', '<p>Vous recevez le don de Style de combat de votre choix (cf. « Dons » pour la liste des dons). Au lieu de choisir l’un de ces dons, vous pouvez choisir l’option ci-dessous.</p><p><b>Combattant druidique.</b> Vous apprenez deux sorts mineurs de Druide de votre choix (la liste des sorts de Druide est consultable dans la section de cette classe). Assistance et poussière d’étoile sont recommandés. Les sorts mineurs choisis sont considérés pour vous comme des sorts de Rôdeur, et la Sagesse est la caractéristique d’incantation associée. Chaque fois que vous recevez un niveau de Rôdeur, vous pouvez remplacer l’un de ces sorts mineurs par un autre sort mineur de Druide.</p>', '', 60),
  (755, 'Sous-classe de Rôdeur', '<p>Vous recevez la sous-classe de Rôdeur de votre choix. La sous-classe Chasseur est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Rôdeur. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sousclasse choisie, à concurrence de votre niveau actuel de Rôdeur.</p>', '', 60),
  (756, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Rôdeur 8, 12 et 16.</p>', '', 60),
  (757, 'Attaque supplémentaire', '<p>Vous pouvez attaquer deux fois au lieu d’une lorsque vous entreprenez l’action Attaque à votre tour.</p>', '', 60),
  (758, 'Arpenteur', '<p>Votre Vitesse augmente de 3 m tant que vous ne portez pas d’armure lourde. Vous disposez en outre d’une Vitesse d’escalade et de nage égales à votre valeur de Vitesse.</p>', '', 60),
  (759, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Rôdeur que vous avez choisie, correspondant à ce niveau.</p>', '', 60),
  (760, 'Expertise', '<p>Choisissez deux de vos maîtrises de compétence ne bénéficiant pas de l’Expertise. Vous recevez l’Expertise dans ces compétences.</p>', '', 60),
  (761, 'Infatigable', '<p>Les forces primitives vous soutiennent désormais lors de vos périples, ce qui vous octroie les bénéfices suivants.</p><p><b>Points de vie temporaires.</b> Au prix de l’action Magie, vous pouvez vous octroyer un nombre de points de vie temporaires égal à 1d8 + votre modificateur de Sagesse (minimum +1). Vous pouvez recourir à cette action autant de fois que votre modificateur de Sagesse (minimum d’une fois) et récupérez ce quota en terminant un Repos long.</p><p><b>Diminuer l’Épuisement.</b> Chaque fois que vous terminez un Repos court, votre éventuel niveau d’Épuisement diminue de 1.</p>', '', 60),
  (762, 'Chasseur implacable', '<p>Subir des dégâts ne peut pas briser votre Concentration sur marque du chasseur.</p>', '', 60),
  (763, 'Voile de la nature', '<p>Vous invoquez les esprits de la nature afin de vous cacher magiquement. Par une action Bonus, vous pouvez vous octroyer l’état Invisible jusqu’à la fin de votre tour suivant.</p><p>Vous pouvez recourir à cette aptitude autant de fois que votre modificateur de Sagesse (minimum d’une fois) et récupérez ce quota en terminant un Repos long.</p>', '', 60),
  (764, 'Chasseur précis', '<p>Vous recevez l’Avantage à vos jets d’attaque contre la créature affectée par votre marque du chasseur.</p>', '', 60),
  (765, 'Sens sauvages', '<p>Fort d’un lien étroit avec les forces de la nature, vous jouissez de la Vision aveugle dans un rayon de 9 m.</p>', '', 60),
  (766, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur de Déplacement dimensionnel est recommandé.</p>', '', 60),
  (767, 'Tueur implacable', '<p>Le dé de dégâts de votre marque du chasseur passe de d6 à d10.</p>', '', 60),
  (768, 'Argot des voleurs', '<p>Vous avez appris diverses langues auprès des communautés dans lesquelles vous avez fait vos armes de Roublard. Vous connaissez l’argot des voleurs et une autre langue, que vous choisissez dans les tables des langues de la section « Création de personnage ».</p>', '', 61),
  (769, 'Attaque sournoise', '<p>Vous savez porter des attaques qui exploitent subtilement les baisses d’attention de l’adversaire. Une fois par tour et à condition que l’attaque soit portée avec une arme dotée de la propriété Finesse ou À distance, vous pouvez infliger 1d6 dégâts supplémentaires à une créature que vous touchez avec un jet d’attaque pour lequel vous avez l’Avantage. Ces dégâts supplémentaires sont du même type que celui de l’arme.</p><p>Vous n’avez pas besoin d’avoir l’Avantage au jet d’attaque si au moins l’un de vos alliés se trouve dans un rayon de 1,50 m de la cible, à condition que cet allié ne subisse pas l’état Neutralisé et que vous ne soyez pas désavantagé au jet d’attaque.</p><p>Ces dégâts supplémentaires augmentent à mesure que vous gagnez des niveaux de Roublard, comme l’indique la colonne Attaque sournoise de la table « Aptitudes du Roublard ».</p>', '', 61),
  (770, 'Bottes d’arme', '<p>Votre entraînement martial vous permet de recourir à la propriété Botte de deux types d’arme de votre choix parmi celles dont vous avez la maîtrise, par exemple la dague et l’arc court.</p><p>Chaque fois que vous terminez un Repos long, vous pouvez changer le type d’arme que vous avez choisi. Vous pourriez par exemple décider d’opter pour les propriétés Bottes du cimeterre et de l’épée courte.</p>', '', 61),
  (771, 'Expertise', '<p>Vous recevez l’Expertise dans deux de vos maîtrises de compétence au choix. Escamotage et Discrétion sont recommandés si vous en avez la maîtrise.</p><p>Au niveau 6 de Roublard, vous recevez l’Expertise dans deux maîtrises de compétences supplémentaires au choix.</p>', '', 61),
  (772, 'Ruse', '<p>Votre esprit vif et votre agilité vous permettent d’agir et de filer promptement. À votre tour, vous pouvez effectuer l’une des actions suivantes par une action Bonus : Désengagement, Furtivité ou Pointe.</p>', '', 61),
  (773, 'Sous-classe de Roublard', '<p>Vous recevez la sous-classe de Roublard de votre choix. La sous-classe Voleur est détaillée après la description de cette classe. Une sous-classe est une spécialisation qui vous octroie des aptitudes à certains niveaux de Roublard. Pour le reste de votre carrière, vous bénéficiez de chacune des aptitudes de la sous-classe choisie, à concurrence de votre niveau actuel de Roublard.</p>', '', 61),
  (774, 'Visée appliquée', '<p>Par une action Bonus, vous vous octroyez l’Avantage à votre prochain jet d’attaque du tour. Vous ne pouvez recourir à cette aptitude que si vous ne vous êtes pas déplacé à ce tour, et votre Vitesse est réduite à 0 jusqu’à la fin du tour.</p>', '', 61),
  (775, 'Amélioration de caractéristique', '<p>Vous recevez le don Amélioration de caractéristique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Vous recevez de nouveau cette aptitude aux niveaux de Roublard 8, 10, 12 et 16.</p>', '', 61),
  (776, 'Frappe malicieuse', '<p>Vous avez mis au point des façons astucieuses d’utiliser votre Attaque sournoise. Lorsque vous infligez des dégâts d’Attaque sournoise, vous pouvez ajouter l’un des effets de Frappe malicieuse ci-après. Chaque effet présente un coût exprimé en dé, qui correspond au nombre de dés d’Attaque sournoise auquel vous renoncez pour ajouter cet effet. Vous retirez le ou les dés avant le lancer, et l’effet se produit immédiatement après que les dégâts de l’attaque ont été infligés. Si, par exemple, vous ajoutez l’effet Poison, retirez 1d6 aux dégâts d’Attaque sournoise avant le lancer.</p><p>Si un effet de Frappe malicieuse entraîne un jet de sauvegarde, le DD est égal à 8 + votre modificateur de Dextérité + votre bonus de maîtrise.</p><p><b>Croc-en-jambe (coût : 1d6).</b> Si la cible est une de taille G ou inférieure, elle doit réussir un jet de sauvegarde de Dextérité sous peine de subir l’état À terre.</p><p><b>Poison (coût : 1d6).</b> Vous ajoutez une toxine à votre coup, contraignant la cible à effectuer un jet de sauvegarde de Constitution. En cas d’échec, la cible subit l’état Empoisonné pendant 1 minute. La cible réitère le JS à la fin de chacun de ses tours et met un terme à l’effet Empoisonné sur elle-même en cas de réussite.</p><p>Pour recourir à cet effet, vous devez avoir un matériel d’empoisonneur sur vous.</p><p><b>Repli (coût : 1d6).</b> Aussitôt après l’attaque, vous vous déplacez à concurrence de la moitié de votre Vitesse sans provoquer d’attaques d’Opportunité.</p>', '', 61),
  (777, 'Esquive instinctive', '<p>Lorsqu’un assaillant que vous voyez vous touche avec un jet d’attaque, vous pouvez jouer votre Réaction pour réduire de moitié les dégâts de cette attaque (arrondir à l’inférieur).</p>', '', 61),
  (778, 'Esquive totale', '<p>Votre agilité vous permet d’esquiver certains dangers. Quand vous êtes soumis à un effet qui vous permet d’effectuer un jet de sauvegarde de Dextérité pour réduire les dégâts de moitié, vous ne subissez aucun dégât en cas de sauvegarde réussie, et seulement la moitié en cas d’échec. Vous ne pouvez pas recourir à cette aptitude si vous subissez l’état Neutralisé.</p>', '', 61),
  (779, 'Savoir-faire', '<p>Chaque fois que vous effectuez un test de caractéristique qui repose sur une compétence ou un outil dont vous avez la maîtrise, tout résultat inférieur ou égal à 9 sur le d20 est considéré comme un 10.</p>', '', 61),
  (780, 'Aptitude de sous-classe', '<p>Vous recevez une aptitude de la sous-classe de Roublard que vous avez choisie, correspondant à ce niveau.</p>', '', 61),
  (781, 'Frappe malicieuse améliorée', '<p>Vous pouvez utiliser jusqu’à deux effets de Frappe malicieuse lorsque vous infligez des dégâts d’Attaque sournoise, en acquittant le coût en dés pour chaque effet.</p>', '', 61),
  (782, 'Coups vicieux', '<p>Vous avez appris de nouveaux coups bas pour « agrémenter » votre Attaque sournoise. Les effets ci-après figurent désormais dans vos options de Frappe malicieuse.</p><p><b>Assommer (coût : 6d6).</b> La cible doit réussir un jet de sauvegarde de Constitution, faute de quoi elle subit l’état Inconscient pendant 1 minute ou jusqu’à ce qu’elle subisse des dégâts. La cible réitère le JS à la fin de chacun de ses tours et met un terme à l’état Inconscient sur elle-même en cas de réussite.</p><p><b>Aveugler (coût : 3d6).</b> La cible doit réussir un jet de sauvegarde de Dextérité, faute de quoi elle subit l’état Aveuglé jusqu’à la fin de son tour suivant.</p><p><b>Hébéter (coût : 2d6).</b> La cible doit réussir un jet de sauvegarde de Constitution faute de quoi, à son tour suivant, elle ne pourra entreprendre que l’une des actions ci-après : déplacement, action ou action Bonus.</p>', '', 61),
  (783, 'Esprit fuyant', '<p>Votre esprit retors est particulièrement difficile à contrôler. Vous recevez la maîtrise des jets de sauvegarde de Sagesse et de Charisme.</p>', '', 61),
  (784, 'Insaisissable', '<p>Vous êtes tellement agile que vos assaillants ont rarement le dessus sur vous. Aucun jet d’attaque ne peut avoir l’Avantage contre vous si vous ne subissez pas l’état Neutralisé.</p>', '', 61),
  (785, 'Faveur épique', '<p>Vous recevez un don de Faveur épique (cf. « Dons ») ou un autre don de votre choix pour lequel vous remplissez les conditions. Faveur de l’esprit nocturne est recommandé.</p>', '', 61),
  (786, 'Coup de chance', '<p>Vous avez le chic pour réussir quand l’enjeu est de taille. Si vous ratez un Test d20, vous pouvez transformer le résultat du jet en 20.</p><p>Une fois que vous avez utilisé cette aptitude, vous devez terminer un Repos court ou long pour pouvoir y recourir de nouveau.</p>', '', 61)
